1	package snapshot
2	
3	import (
4		"bufio"
5		"encoding/binary"
6		"errors"
7		"hash/crc32"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12	)
13	
14	// Hot backup and restore.
15	//
16	// A backup exports the store's complete committed state at one fixed commit
17	// watermark as a portable, segmented artifact. The export anchors to the
18	// current view and then streams its terminal entries into self-describing,
19	// checksummed segments without holding the store's write lock: writes,
20	// deletes, batch commits, snapshots, cursor paging, checkpoints and
21	// compactions proceed concurrently and never block on the disk writes the
22	// backup performs. Reads keep hitting memory exactly as before.
23	//
24	// Artifact layout, inside the output directory:
25	//
26	//	backup.tmp/                staging area while an export runs
27	//	segment-XXXXX.dat          finished segments, promoted one at a time
28	//	manifest.dat               present only when the whole export finished
29	//
30	// The artifact is complete if and only if manifest.dat is present, intact and
31	// agrees exactly with the segment files that exist; Restore rejects anything
32	// short of that wholesale with fs.ErrInvalid. A kill at any instant therefore
33	// leaves either the previous contents of the directory or one complete
34	// artifact; staging debris and an orphaned manifest temp are swept at the
35	// start of the next backup into that directory or the next Open of it, and
36	// the store being backed up is never touched.
37	//
38	// Segment file layout (all integers little-endian):
39	//
40	//	magic      uint32   backupMagic
41	//	version    uint32   backupVersion
42	//	watermark  uint64   highest commit sequence exported
43	//	snapshots  uint64   cumulative snapshot count at the export watermark
44	//	index      uint32   segment position, starting at 0
45	//	count      uint32   number of entries in this segment
46	//	cumulative uint64   cumulative live-entry count through this segment
47	//	entries    [count]entry
48	//	crc        uint32   IEEE CRC-32 of every preceding byte of the file
49	//
50	// One entry is a flags byte (0 = put, 1 = tombstone), a uint32 key length, a
51	// uint32 value length, the entry's commit sequence (uint64), the key, then
52	// the value. Entries are written in ascending key order; a put carries its
53	// value bytes, a tombstone carries none.
54	//
55	// The manifest repeats the artifact-level fields (magic, version, watermark,
56	// snapshots, total entry count, segment count) and one record per segment
57	// (its index, entry count, cumulative count and content CRC), terminated by
58	// an overall CRC. A segment is accepted only when its own CRC verifies and
59	// every field the manifest records about it matches: a missing segment, a
60	// truncated segment, a checksum mismatch, an unknown version or a manifest
61	// that disagrees with the files rejects the entire artifact.
62	const (
63		backupStageDir    = "backup.tmp"
64		backupManifest    = "manifest.dat"
65		backupManifestTmp = "manifest.dat.tmp"
66		backupSegmentPref = "segment-"
67		backupSegmentSufx = ".dat"
68	
69		backupMagic   uint32 = 0x42414b53 // bytes "SKAB"
70		backupVersion uint32 = 1
71	
72		// backupSegHeaderSize is magic, version, watermark, snapshots, index,
73		// count, cumulative.
74		backupSegHeaderSize = 4 + 4 + 8 + 8 + 4 + 4 + 8
75		// backupManifestSize is magic, version, watermark, snapshots, total
76		// entries and segment count; the terminal overall CRC follows the
77		// per-segment records.
78		backupManifestSize = 4 + 4 + 8 + 8 + 8 + 4
79		// backupSegRecSize is one manifest per-segment record: index, count,
80		// cumulative, content CRC.
81		backupSegRecSize = 4 + 4 + 8 + 4
82		// backupEntriesPerSegment bounds how many entries one segment holds. The
83		// export streams entries a chunk this size and flushes a segment per
84		// chunk, so the whole keyspace is never copied out before hitting disk;
85		// only one chunk of values is resident at a time. It is a write-chunking
86		// target, not a format limit.
87		backupEntriesPerSegment = 4096
88		// backupMaxSegments is a sanity ceiling on the segment count a manifest
89		// may declare, bounding pre-allocation when reading an untrusted file.
90		backupMaxSegments = 1 << 20
91	)
92	
93	// backupAnchor is the fixed point-in-time state an export streams. It is
94	// captured under the store lock and is immutable afterwards: published views
95	// are never mutated, so the streaming that follows takes no lock and cannot
96	// observe commits made after the anchor.
97	type backupAnchor struct {
98		view      *view
99		watermark uint64 // highest commit sequence covered
100		snaps     uint64 // cumulative snapshot count covered
101	}
102	
103	// backupEntry is one terminal key state in export order.
104	type backupEntry struct {
105		key     string
106		value   []byte
107		seq     uint64
108		present bool
109	}
110	
111	// Backup exports the store's complete committed state into outDir as a
112	// portable, segmented backup anchored at the commit watermark current when
113	// Backup anchors. Writes and deletes committed after the anchor are not
114	// included and proceed concurrently without blocking; every lock-free read
115	// keeps hitting memory and is never held up by the export's disk writes.
116	//
117	// The export streams the keyspace in fixed-size segments and never copies the
118	// whole keyspace out before writing it. It is all-or-nothing: segment files
119	// are built and synced in a staging directory and promoted one at a time; the
120	// manifest is written last and only becomes visible once every segment it
121	// names is durable. A process killed at any point leaves no half artifact in
122	// outDir — staging debris is swept at the start of the next Backup there (or
123	// the next Open of that directory) and never affects the backed-up store.
124	//
125	// A path that does not exist or is not a directory, or a directory that
126	// already holds a complete or partial artifact or any unrelated entry, is
127	// rejected with an error wrapping fs.ErrInvalid. Backup on a closed store
128	// returns an error wrapping fs.ErrClosed.
129	func (s *Store) Backup(outDir string) error {
130		if s.closed.Load() {
131			return errStoreClosed
132		}
133		if outDir == "" {
134			return errBadBackup
135		}
136	
137		// Prepare the output directory and clear debris from an export killed
138		// mid-run, before touching the store. A finished artifact or any foreign
139		// entry is never overwritten. Debris from a chain merge killed mid-commit
140		// next to this directory is repaired or swept first.
141		sweepMergeDebris(outDir)
142		info, err := os.Stat(outDir)
143		if err != nil {
144			if !errors.Is(err, os.ErrNotExist) {
145				return err
146			}
147			if err := os.MkdirAll(outDir, 0o700); err != nil {
148				return err
149			}
150		} else if !info.IsDir() {
151			return errBadBackup
152		}
153		if err := prepareBackupDir(outDir); err != nil {
154			return err
155		}
156	
157		// Anchor at one fixed watermark. This is the only moment the export takes
158		// the write lock; everything after it streams from an immutable view.
159		s.mu.Lock()
160		if s.closed.Load() {
161			s.mu.Unlock()
162			return errStoreClosed
163		}
164		anchor := backupAnchor{
165			view:      s.current.Load(),
166			watermark: s.nextSeq,
167			snaps:     s.snapshots.Load(),
168		}
169		s.mu.Unlock()
170	
171		return writeBackup(outDir, anchor)
172	}
173	
174	// prepareBackupDir makes outDir an empty target for a fresh artifact: it
175	// removes staging debris and orphaned files from an interrupted export and
176	// refuses to overwrite a finished artifact or any unrelated entry.
177	func prepareBackupDir(outDir string) error {
178		entries, err := os.ReadDir(outDir)
179		if err != nil {
180			return err
181		}
182		for _, e := range entries {
183			name := e.Name()
184			switch {
185			case e.IsDir() && (name == backupStageDir || name == incrStageDir):
186				// staging debris, removed below
187			case !e.IsDir() && (isBackupSegmentName(name) || isBackupRingName(name) || name == backupManifestTmp):
188				// orphaned by a kill, removed below
189			default:
190				return errBadBackup
191			}
192		}
193		for _, stage := range []string{backupStageDir, incrStageDir} {
194			if err := os.RemoveAll(filepath.Join(outDir, stage)); err != nil {
195				return err
196			}
197		}
198		for _, e := range entries {
199			if e.IsDir() {
200				continue
201			}
202			name := e.Name()
203			if isBackupSegmentName(name) || isBackupRingName(name) || name == backupManifestTmp {
204				if err := os.Remove(filepath.Join(outDir, name)); err != nil &&
205					!errors.Is(err, os.ErrNotExist) {
206					return err
207				}
208			}
209		}
210		return syncDirectory(outDir)
211	}
212	
213	// isBackupRingName reports whether name is a finished incremental ring file.
214	func isBackupRingName(name string) bool {
215		_, ok := parseRingIndex(name)
216		return ok
217	}
218	
219	// isBackupSegmentName reports whether name is a finished segment file name.
220	func isBackupSegmentName(name string) bool {
221		return len(name) > len(backupSegmentPref)+len(backupSegmentSufx) &&
222			name[:len(backupSegmentPref)] == backupSegmentPref &&
223			name[len(name)-len(backupSegmentSufx):] == backupSegmentSufx
224	}
225	
226	// parseSegmentIndex is the inverse of segmentName. ok is false for names that
227	// are not well-formed finished segment files.
228	func parseSegmentIndex(name string) (uint32, bool) {
229		const body = "0000000000"
230		mid := len(backupSegmentPref) + len(body)
231		if len(name) != mid+len(backupSegmentSufx) ||
232			name[:len(backupSegmentPref)] != backupSegmentPref ||
233			name[mid:] != backupSegmentSufx {
234			return 0, false
235		}
236		var n uint32
237		for i := len(backupSegmentPref); i < mid; i++ {
238			c := name[i]
239			if c < '0' || c > '9' {
240				return 0, false
241			}
242			n = n*10 + uint32(c-'0')
243		}
244		return n, true
245	}
246	
247	// segmentName renders a segment index as a fixed-width, zero-padded name.
248	func segmentName(index uint32) string {
249		const digits = "0123456789"
250		buf := make([]byte, 10)
251		n := index
252		for i := len(buf) - 1; i >= 0; i-- {
253			buf[i] = digits[n%10]
254			n /= 10
255		}
256		return backupSegmentPref + string(buf) + backupSegmentSufx
257	}
258	
259	// writeBackup streams the anchor's terminal entries into segments and finishes
260	// with the manifest. It holds no store lock: the anchored view is immutable.
261	func writeBackup(outDir string, anchor backupAnchor) error {
262		stage := filepath.Join(outDir, backupStageDir)
263		if err := os.MkdirAll(stage, 0o700); err != nil {
264			return err
265		}
266		cleanup := func() {
267			os.RemoveAll(stage)
268			if entries, rerr := os.ReadDir(outDir); rerr == nil {
269				for _, e := range entries {
270					if !e.IsDir() && isBackupSegmentName(e.Name()) {
271						os.Remove(filepath.Join(outDir, e.Name()))
272					}
273				}
274				os.Remove(filepath.Join(outDir, backupManifestTmp))
275			}
276			_ = syncDirectory(outDir)
277		}
278	
279		// One index pass over the immutable view yields the sorted live keys.
280		// Only present keys are exported: a restore rebuilds a fresh log with no
281		// older history to mask, so deleted keys are simply absent — exactly as a
282		// compaction drops them. This keeps the artifact proportional to live
283		// data, not the cumulative set of every key ever touched. Values are not
284		// collected here; they are read and written a chunk at a time below, so the
285		// whole keyspace is never resident before hitting disk.
286		var keys []string
287		anchor.view.rangeEach(func(k string, n *node) bool {
288			if n.present {
289				keys = append(keys, k)
290			}
291			return true
292		})
293		sort.Strings(keys)
294	
295		var segments []manifestSegment
296		var total uint64
297		var index uint32
298	
299		for start := 0; start < len(keys); start += backupEntriesPerSegment {
300			stop := start + backupEntriesPerSegment
301			if stop > len(keys) {
302				stop = len(keys)
303			}
304			entries := make([]backupEntry, 0, stop-start)
305			for _, k := range keys[start:stop] {
306				n := anchor.view.lookup(k)
307				if n == nil || !n.present {
308					continue
309				}
310				entries = append(entries, backupEntry{
311					key:     k,
312					seq:     n.seq,
313					present: true,
314					value:   cloneBytes(n.value),
315				})
316			}
317			cumulative := total + uint64(len(entries))
318			crc, err := writeSegment(stage, index, anchor, cumulative, entries)
319			if err != nil {
320				cleanup()
321				return err
322			}
323			// Promote the fully synced segment out of staging. A crash exposes at
324			// worst a finished segment without the manifest, which is pure debris;
325			// it never exposes a partial file under a finished name.
326			if err := os.Rename(
327				filepath.Join(stage, segmentName(index)),
328				filepath.Join(outDir, segmentName(index)),
329			); err != nil {
330				cleanup()
331				return err
332			}
333			if err := syncDirectory(outDir); err != nil {
334				cleanup()
335				return err
336			}
337			segments = append(segments, manifestSegment{
338				index:      index,
339				count:      uint32(len(entries)),
340				cumulative: cumulative,
341				crc:        crc,
342			})
343			total = cumulative
344			index++
345		}
346	
347		// The manifest is the commit point: it names exactly the durable segment
348		// set and carries the artifact metadata. Building it last makes the whole
349		// export all-or-nothing.
350		if err := writeManifest(outDir, stage, anchor, total, segments); err != nil {
351			cleanup()
352			return err
353		}
354		if err := os.RemoveAll(stage); err != nil {
355			return err
356		}
357		return syncDirectory(outDir)
358	}
359	
360	// writeSegment serializes one fully synced segment file in dir and returns the
361	// content CRC written into its terminal checksum field.
362	func writeSegment(dir string, index uint32, anchor backupAnchor, cumulative uint64, entries []backupEntry) (uint32, error) {
363		path := filepath.Join(dir, segmentName(index))
364		tmp, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o600)
365		if err != nil {
366			return 0, err
367		}
368		fail := func(err error) (uint32, error) {
369			tmp.Close()
370			os.Remove(path)
371			return 0, err
372		}
373	
374		w := bufio.NewWriter(tmp)
375		head := make([]byte, backupSegHeaderSize)
376		binary.LittleEndian.PutUint32(head[0:4], backupMagic)
377		binary.LittleEndian.PutUint32(head[4:8], backupVersion)
378		binary.LittleEndian.PutUint64(head[8:16], anchor.watermark)
379		binary.LittleEndian.PutUint64(head[16:24], anchor.snaps)
380		binary.LittleEndian.PutUint32(head[24:28], index)
381		binary.LittleEndian.PutUint32(head[28:32], uint32(len(entries)))
382		binary.LittleEndian.PutUint64(head[32:40], cumulative)
383	
384		h := crc32.NewIEEE()
385		if _, err := w.Write(head); err != nil {
386			return fail(err)
387		}
388		h.Write(head)
389	
390		ehdr := make([]byte, checkpointEntrySize)
391		for _, e := range entries {
392			if len(e.key) > maxRecord || len(e.value) > maxRecord {
393				return fail(errors.New("snapshot: backup entry too large"))
394			}
395			if e.present {
396				ehdr[0] = ckptFlagPut
397			} else {
398				ehdr[0] = ckptFlagDelete
399			}
400			binary.LittleEndian.PutUint32(ehdr[1:5], uint32(len(e.key)))
401			binary.LittleEndian.PutUint32(ehdr[5:9], uint32(len(e.value)))
402			binary.LittleEndian.PutUint64(ehdr[9:17], e.seq)
403			if _, err := w.Write(ehdr); err != nil {
404				return fail(err)
405			}
406			h.Write(ehdr)
407			if _, err := io.WriteString(w, e.key); err != nil {
408				return fail(err)
409			}
410			h.Write([]byte(e.key))
411			if len(e.value) > 0 {
412				if _, err := w.Write(e.value); err != nil {
413					return fail(err)
414				}
415				h.Write(e.value)
416			}
417		}
418	
419		crc := h.Sum32()
420		var crcb [crcSize]byte
421		binary.LittleEndian.PutUint32(crcb[:], crc)
422		if _, err := w.Write(crcb[:]); err != nil {
423			return fail(err)
424		}
425		if err := w.Flush(); err != nil {
426			return fail(err)
427		}
428		if err := tmp.Sync(); err != nil {
429			return fail(err)
430		}
431		if err := tmp.Close(); err != nil {
432			os.Remove(path)
433			return 0, err
434		}
435		return crc, nil
436	}
437	
438	// manifestInfo is the validated content of manifest.dat.
439	type manifestInfo struct {
440		watermark uint64
441		snaps     uint64
442		total     uint64
443		crc       uint32 // manifest terminal content CRC; the first ring links to it
444		segments  []manifestSegment
445	}
446	
447	// manifestSegment describes one segment the manifest names.
448	type manifestSegment struct {
449		index      uint32
450		count      uint32
451		cumulative uint64
452		crc        uint32
453	}
454	
455	// writeManifest builds and durably installs the manifest, the export's commit
456	// point. It is written under a temp name in the staging directory, synced,
457	// renamed into outDir and followed by a directory force.
458	func writeManifest(outDir, stage string, anchor backupAnchor, total uint64, segs []manifestSegment) error {
459		if err := os.MkdirAll(stage, 0o700); err != nil {
460			return err
461		}
462		tmpPath := filepath.Join(stage, backupManifestTmp)
463		tmp, err := os.OpenFile(tmpPath, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o600)
464		if err != nil {
465			return err
466		}
467		fail := func(err error) error {
468			tmp.Close()
469			os.Remove(tmpPath)
470			return err
471		}
472	
473		w := bufio.NewWriter(tmp)
474		head := make([]byte, backupManifestSize)
475		binary.LittleEndian.PutUint32(head[0:4], backupMagic)
476		binary.LittleEndian.PutUint32(head[4:8], backupVersion)
477		binary.LittleEndian.PutUint64(head[8:16], anchor.watermark)
478		binary.LittleEndian.PutUint64(head[16:24], anchor.snaps)
479		binary.LittleEndian.PutUint64(head[24:32], total)
480		binary.LittleEndian.PutUint32(head[32:36], uint32(len(segs)))
481		h := crc32.NewIEEE()
482		if _, err := w.Write(head); err != nil {
483			return fail(err)
484		}
485		h.Write(head)
486	
487		rec := make([]byte, backupSegRecSize)
488		for _, s := range segs {
489			binary.LittleEndian.PutUint32(rec[0:4], s.index)
490			binary.LittleEndian.PutUint32(rec[4:8], s.count)
491			binary.LittleEndian.PutUint64(rec[8:16], s.cumulative)
492			binary.LittleEndian.PutUint32(rec[16:20], s.crc)
493			if _, err := w.Write(rec); err != nil {
494				return fail(err)
495			}
496			h.Write(rec)
497		}
498		var crcb [crcSize]byte
499		binary.LittleEndian.PutUint32(crcb[:], h.Sum32())
500		if _, err := w.Write(crcb[:]); err != nil {
501			return fail(err)
502		}
503		if err := w.Flush(); err != nil {
504			return fail(err)
505		}
506		if err := tmp.Sync(); err != nil {
507			return fail(err)
508		}
509		if err := tmp.Close(); err != nil {
510			os.Remove(tmpPath)
511			return err
512		}
513		if err := os.Rename(tmpPath, filepath.Join(outDir, backupManifest)); err != nil {
514			os.Remove(tmpPath)
515			return err
516		}
517		return syncDirectory(outDir)
518	}
519	
520	// sweepBackupDebris removes temporary files an export killed before its commit
521	// point can leave in a directory: the full and incremental staging
522	// directories and a manifest temp. Finished segment and ring files are left
523	// here (only the next backup into that directory reclaims them); the manifest,
524	// when present, is never touched.
525	func sweepBackupDebris(dir string) error {
526		for _, stage := range []string{backupStageDir, incrStageDir} {
527			if err := os.RemoveAll(filepath.Join(dir, stage)); err != nil &&
528				!errors.Is(err, os.ErrNotExist) {
529				return err
530			}
531		}
532		if err := os.Remove(filepath.Join(dir, backupManifestTmp)); err != nil &&
533			!errors.Is(err, os.ErrNotExist) {
534			return err
535		}
536		return nil
537	}
538

