386	// artifactInfo is a fully validated backup chain directory.
387	type artifactInfo struct {
388		head      manifestInfo
389		ringCount uint32 // number of rings dense after the head
390		tipCRC    uint32 // content CRC the next ring must link to
391		endWM     uint64 // watermark of the chain tip
392		snaps     uint64 // cumulative snapshot count at the chain tip
393		// ringSums holds the validated summary of every ring, in chain order
394		// (ringSums[i] describes ring i+1). MergeChain uses it to re-link the
395		// rings that survive a merge without re-streaming the chain.
396		ringSums []ringSummary
397	}
398	
399	// validateBackupChain inspects backupDir as one whole chain: the head
400	// manifest, an exact dense head segment set and dense linked rings with
401	// continuous watermarks. It streams every file and holds no entry content.
402	// Any defect returns an error wrapping fs.ErrInvalid; genuine read failures
403	// pass through unchanged.
404	func validateBackupChain(backupDir string) (artifactInfo, error) {
405		var zero artifactInfo
406		head, err := loadBackupManifest(backupDir)
407		if err != nil {
408			return zero, err
409		}
410	
411		entries, err := os.ReadDir(backupDir)
412		if err != nil {
413			return zero, err
414		}
415		headSegs := make(map[uint32]bool, len(head.segments))
416		for _, s := range head.segments {
417			headSegs[s.index] = true
418		}
419		ringSet := make(map[uint32]bool)
420		sawManifest := false
421		for _, e := range entries {
422			name := e.Name()
423			if e.IsDir() {
424				return zero, errBadBackup // no staging or foreign directory in an artifact
425			}
426			switch {
427			case name == backupManifest:
428				sawManifest = true
429			case name == backupManifestTmp:
430				return zero, errBadBackup
431			default:
432				if idx, ok := parseSegmentIndex(name); ok {
433					if !headSegs[idx] {
434						return zero, errBadBackup
435					}
436					headSegs[idx] = false // mark present
437					continue
438				}
439				if idx, ok := parseRingIndex(name); ok {
440					if ringSet[idx] {
441						return zero, errBadBackup
442					}
443					ringSet[idx] = true
444					continue
445				}
446				return zero, errBadBackup // foreign file
447			}
448		}
449		if !sawManifest {
450			return zero, errBadBackup
451		}
452		for idx, missing := range headSegs {
453			if missing {
454				_ = idx
455				return zero, errBadBackup // a manifest-named segment is absent
456			}
457		}
458	
459		// Deep-validate the head segments before trusting any of the chain.
460		if err := streamHeadSegments(backupDir, head, nil); err != nil {
461			return zero, err
462		}
463	
464		// Validate the dense ring sequence and its linkage.
465		ringCount := uint32(len(ringSet))
466		for idx := uint32(1); idx <= ringCount; idx++ {
467			if !ringSet[idx] {
468				return zero, errBadBackup // gap in the rings
469			}
470		}
471		prevWM := head.watermark
472		prevSnaps := head.snaps
473		prevLink := head.crc
474		tipCRC := head.crc
475		ringSums := make([]ringSummary, 0, ringCount)
476		for idx := uint32(1); idx <= ringCount; idx++ {
477			f, oerr := os.Open(filepath.Join(backupDir, ringName(idx)))
478			if oerr != nil {
479				return zero, oerr
480			}
481			sum, serr := scanRing(f, ringExpect{
482				index:    idx,
483				prevLink: prevLink,
484				startWM:  prevWM,
485			}, nil)
486			f.Close()
487			if serr != nil {
488				return zero, serr
489			}
490			if sum.snaps < prevSnaps {
491				return zero, errBadBackup
492			}
493			ringSums = append(ringSums, sum)
494			prevWM = sum.endWM
495			prevSnaps = sum.snaps
496			prevLink = sum.fileCRC
497			tipCRC = sum.fileCRC
498		}
499		return artifactInfo{
500			head:      head,
501			ringCount: ringCount,
502			tipCRC:    tipCRC,
503			endWM:     prevWM,
504			snaps:     prevSnaps,
505			ringSums:  ringSums,
506		}, nil
507	}
