509	// dirHasRings reports whether backupDir names at least one finished ring
510	// file. Its only read error passes through from the directory listing.
511	func dirHasRings(backupDir string) (bool, error) {
512		entries, err := os.ReadDir(backupDir)
513		if err != nil {
514			return false, err
515		}
516		for _, e := range entries {
517			if !e.IsDir() {
518				if _, ok := parseRingIndex(e.Name()); ok {
519					return true, nil
520				}
521			}
522		}
523		return false, nil
524	}
