526	// buildChainRestoredStore streams a validated head-plus-rings chain into a
527	// fresh wal.log in the staging directory, applying the artifacts in chain
528	// order (each ring overriding the one before) so the result is exactly the
529	// terminal state at the chain tip. It streams one entry at a time and keeps
530	// no keyspace in memory.
531	//
532	// Frames are re-sequenced densely in application order: a key's own frames
533	// are encountered head-before-ring and in ring order, so its per-key sequence
534	// keeps increasing; replay therefore links the same terminal the chain
535	// computes. The snapshot count at the tip is appended as the closing meta,
536	// the same compacted-log shape buildRestoredStore writes. Nothing is
537	// installed until this whole step succeeds.
538	func buildChainRestoredStore(stage, backupDir string, art artifactInfo) error {
539		wf, err := os.OpenFile(filepath.Join(stage, walName), os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
540		if err != nil {
541			return err
542		}
543		fail := func(err error) error {
544			wf.Close()
545			return err
546		}
547		l := &walWriter{f: wf, w: bufio.NewWriter(wf)}
548		var seq uint64
549	
550		apply := func(flag byte, key string, value []byte, _ uint64) error {
551			seq++
552			if flag == ckptFlagPut {
553				return l.encodeFrameSeq(opPutSeq, key, seq, value)
554			}
555			return l.encodeFrameSeq(opDeleteSeq, key, seq, nil)
556		}
557	
558		if err := streamHeadSegments(backupDir, art.head, apply); err != nil {
559			return fail(err)
560		}
561		prevWM := art.head.watermark
562		prevLink := art.head.crc
563		for idx := uint32(1); idx <= art.ringCount; idx++ {
564			f, oerr := os.Open(filepath.Join(backupDir, ringName(idx)))
565			if oerr != nil {
566				return fail(oerr)
567			}
568			sum, serr := scanRing(f, ringExpect{
569				index:    idx,
570				prevLink: prevLink,
571				startWM:  prevWM,
572			}, apply)
573			f.Close()
574			if serr != nil {
575				return fail(serr)
576			}
577			prevWM = sum.endWM
578			prevLink = sum.fileCRC
579		}
580	
581		if art.snaps > 0 {
582			var v [metaValueSize]byte
583			binary.LittleEndian.PutUint64(v[:], art.snaps)
584			if err := l.encodeFrame(opMeta, "", v[:]); err != nil {
585				return fail(err)
586			}
587		}
588		if err := l.w.Flush(); err != nil {
589			return fail(err)
590		}
591		if err := wf.Sync(); err != nil {
592			return fail(err)
593		}
594		if err := wf.Close(); err != nil {
595			return err
596		}
597		return syncDirectory(stage)
598	}
599	
600	// presentSetAtTip streams the whole validated chain and returns the set of
601	// keys present at its tip. It is one set of live keys (bounded by live data,
602	// never by the chain length), not a copy of any value: the next incremental
603	// export needs exactly this set to tell an untouched key from one touched,
604	// deleted and then forgotten by compaction.
605	func presentSetAtTip(backupDir string, art artifactInfo) (map[string]struct{}, error) {
606		present := make(map[string]struct{})
607		add := func(flag byte, key string, _ []byte, _ uint64) error {
608			if flag == ckptFlagPut {
609				present[key] = struct{}{}
610			} else {
611				delete(present, key)
612			}
613			return nil
614		}
615		if err := streamHeadSegments(backupDir, art.head, add); err != nil {
616			return nil, err
617		}
618		prevWM := art.head.watermark
619		prevLink := art.head.crc
620		for idx := uint32(1); idx <= art.ringCount; idx++ {
621			f, err := os.Open(filepath.Join(backupDir, ringName(idx)))
622			if err != nil {
623				return nil, err
624			}
625			sum, serr := scanRing(f, ringExpect{
626				index:    idx,
627				prevLink: prevLink,
628				startWM:  prevWM,
629			}, add)
630			f.Close()
631			if serr != nil {
632				return nil, serr
633			}
634			prevWM = sum.endWM
635			prevLink = sum.fileCRC
636		}
637		return present, nil
638	}
639	
640	// ringEntryKind marks one touched key's terminal state for a new ring.
641	type ringEntryKind struct {
642		key    string
643		seq    uint64
644		delete bool
645	}
646	
647	// BackupIncremental appends one incremental ring to the backup chain in
648	// chainDir, anchored at the commit watermark current when it anchors. The
649	// chain directory must already hold a complete full backup (the chain head);
650	// writes and deletes committed after the anchor do not enter the ring, while
651	// the foreground keeps committing.
652	//
653	// The ring holds only the terminal state of keys touched between the chain
654	// tip's watermark and the anchor: later puts overwrite earlier ones, and keys
655	// deleted in the interval are recorded as tombstones and read back as misses
656	// after synthesis. Keys the compaction has forgotten entirely but the chain
657	// once held are recorded as tombstones too, so a delete is never resurrected
658	// by a later compaction of the backed-up store.
659	//
660	// The ring is streamed in bounded chunks and installed all-or-nothing under
661	// a staging name: a kill at any instant leaves the chain exactly as it was
662	// (staging debris is swept at the next export into, or Open of, the
663	// directory), and the backed-up store is never modified.
664	//
665	// A chain directory that is missing, not a directory, incomplete or damaged
666	// (a missing ring, a broken link, a non-continuous watermark, truncation,
667	// checksum failure or unknown version), or a chain advanced concurrently
668	// during the export, rejects the whole operation with an error wrapping
669	// fs.ErrInvalid and leaves no partial ring. BackupIncremental on a closed
670	// store returns an error wrapping fs.ErrClosed.
671	func (s *Store) BackupIncremental(chainDir string) error {
672		if s.closed.Load() {
673			return errStoreClosed
674		}
675		// Serialize exports driven by one store so they can never share a staging
676		// directory or race to append the same ring index. This does not serialize
677		// with commits or reads.
678		s.backupMu.Lock()
679		defer s.backupMu.Unlock()
680		if s.closed.Load() {
681			return errStoreClosed
682		}
683		if chainDir == "" {
684			return errBadBackup
685		}
686		// Repair or clear debris from a merge killed mid-commit before inspecting
687		// the chain.
688		sweepMergeDebris(chainDir)
689		info, err := os.Stat(chainDir)
690		if err != nil {
691			if errors.Is(err, os.ErrNotExist) {
692				return errBadBackup
693			}
694			return err
695		}
696		if !info.IsDir() {
697			return errBadBackup
698		}
699		// Clear staging debris from an export (full or incremental) killed mid-run
700		// before inspecting the chain; a manifest temp is pure debris as well.
701		for _, stage := range []string{incrStageDir, backupStageDir} {
702			if err := os.RemoveAll(filepath.Join(chainDir, stage)); err != nil {
703				return err
704			}
705		}
706		if err := os.Remove(filepath.Join(chainDir, backupManifestTmp)); err != nil &&
707			!errors.Is(err, os.ErrNotExist) {
708			return err
709		}
710	
711		art, err := validateBackupChain(chainDir)
712		if err != nil {
713			return err
714		}
715		// The chain tip's present-key set is the baseline the touched set is
716		// diffed against. Streamed from immutable artifacts, it needs no lock.
717		prevPresent, err := presentSetAtTip(chainDir, art)
718		if err != nil {
719			return err
720		}
721	
722		// Anchor at one fixed watermark. This is the only moment the export takes
723		// the write lock; entry resolution and streaming run on the immutable
724		// anchored view without it.
725		s.mu.Lock()
726		if s.closed.Load() {
727			s.mu.Unlock()
728			return errStoreClosed
729		}
730		anchor := backupAnchor{
731			view:      s.current.Load(),
732			watermark: s.nextSeq,
733			snaps:     s.snapshots.Load(),
734		}
735		s.mu.Unlock()
736	
737		startWM := art.endWM
738		// The anchor must be a continuation of the chain: a watermark or snapshot
739		// count behind the tip means this store cannot extend that chain, so the
740		// export is rejected wholesale before any ring file is staged.
741		if anchor.watermark < startWM || anchor.snaps < art.snaps {
742			return errBadBackup
743		}
744		touched := collectTouchedKeys(anchor.view, prevPresent, startWM, anchor.watermark)
745	
746		index := art.ringCount + 1
747		return writeIncrementalRing(chainDir, ringHeader{
748			index:    index,
749			prevLink: art.tipCRC,
750			startWM:  startWM,
751			endWM:    anchor.watermark,
752			snaps:    anchor.snaps,
753		}, anchor, touched)
754	}
755	
756	// ringHeader carries the fixed fields of a ring being written.
757	type ringHeader struct {
758		index    uint32
759		prevLink uint32
760		startWM  uint64
761		endWM    uint64
762		snaps    uint64
763	}
764	
765	// collectTouchedKeys diffs the anchored view against the present-key set the
766	// chain held at startWM and returns the touched keys' terminal state, sorted
767	// by key. A key present in the chain but absent from the view was deleted and
768	// forgotten by compaction; it still enters the ring as a tombstone, stamped
769	// at the anchor watermark.
770	func collectTouchedKeys(v *view, prevPresent map[string]struct{}, startWM, endWM uint64) []ringEntryKind {
771		var touched []ringEntryKind
772		seen := make(map[string]struct{}, len(prevPresent))
773		v.rangeEach(func(k string, n *node) bool {
774			seen[k] = struct{}{}
775			_, was := prevPresent[k]
776			if n.present {
777				if !was || n.seq > startWM {
778					touched = append(touched, ringEntryKind{key: k, seq: n.seq})
779				}
780			} else if was {
781				touched = append(touched, ringEntryKind{key: k, seq: n.seq, delete: true})
782			}
783			return true
784		})
785		// Keys the chain knew but the view no longer even mentions: deleted and
786		// dropped by a compaction. Stamp the tombstone at the anchor.
787		for k := range prevPresent {
788			if _, ok := seen[k]; ok {
789				continue
790			}
791			touched = append(touched, ringEntryKind{key: k, seq: endWM, delete: true})
792		}
793		sort.Slice(touched, func(i, j int) bool { return touched[i].key < touched[j].key })
794		return touched
795	}
796	
797	// writeIncrementalRing streams one ring in bounded chunks, fully syncs it in
798	// the staging directory and links it into place atomically (link fails
799	// rather than overwrite when another export advanced the chain). The chain
800	// directory is forced afterwards.
801	func writeIncrementalRing(chainDir string, hdr ringHeader, anchor backupAnchor, touched []ringEntryKind) error {
802		final := ringName(hdr.index)
803	
804		// Refuse to build before staging anything if another ring of this index
805		// already exists: a concurrent export appended first.
806		if _, err := os.Stat(filepath.Join(chainDir, final)); err == nil {
807			return errBadBackup
808		} else if !errors.Is(err, os.ErrNotExist) {
809			return err
810		}
811	
812		stage := filepath.Join(chainDir, incrStageDir)
813		if err := os.MkdirAll(stage, 0o700); err != nil {
814			if errors.Is(err, os.ErrExist) {
815				// A non-directory entry occupies the staging name: foreign debris,
816				// never a usable chain.
817				return errBadBackup
818			}
819			return err
820		}
821		tmpPath := filepath.Join(stage, final)
822		cleanup := func() { os.RemoveAll(stage) }
823	
824		tmp, err := os.OpenFile(tmpPath, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
825		if err != nil {
826			if errors.Is(err, os.ErrExist) {
827				// Another export is already staging this ring: this store cannot
828				// also append it.
829				cleanup()
830				return errBadBackup
831			}
832			cleanup()
833			return err
834		}
835		fail := func(err error) error {
836			tmp.Close()
837			cleanup()
838			return err
839		}
840	
841		w := bufio.NewWriter(tmp)
842		hf := crc32.NewIEEE()
843		// write bytes to the ring, advancing the whole-file CRC for every byte.
844		write := func(b []byte) error {
845			if _, err := w.Write(b); err != nil {
846				return err
847			}
848			hf.Write(b)
849			return nil
850		}
851	
852		segCount := uint32(0)
853		if len(touched) > 0 {
854			segCount = uint32((len(touched) + backupEntriesPerSegment - 1) / backupEntriesPerSegment)
855		}
856	
857		head := make([]byte, incrRingHeaderSize)
858		binary.LittleEndian.PutUint32(head[0:4], backupMagic)
859		binary.LittleEndian.PutUint32(head[4:8], backupVersion)
860		binary.LittleEndian.PutUint32(head[8:12], hdr.index)
861		binary.LittleEndian.PutUint32(head[12:16], hdr.prevLink)
862		binary.LittleEndian.PutUint64(head[16:24], hdr.startWM)
863		binary.LittleEndian.PutUint64(head[24:32], hdr.endWM)
864		binary.LittleEndian.PutUint64(head[32:40], hdr.snaps)
865		binary.LittleEndian.PutUint32(head[40:44], segCount)
866		if err := write(head); err != nil {
867			return fail(err)
868		}
869	
870		ehdr := make([]byte, checkpointEntrySize)
871		var segChain uint32
872		var cumulative uint64
873		for seg := uint32(0); seg < segCount; seg++ {
874			start := int(seg) * backupEntriesPerSegment
875			stop := start + backupEntriesPerSegment
876			if stop > len(touched) {
877				stop = len(touched)
878			}
879			chunk := touched[start:stop]
880	
881			hs := crc32.NewIEEE()
882			sh := make([]byte, incrSegHeaderSize)
883			binary.LittleEndian.PutUint32(sh[0:4], backupMagic)
884			binary.LittleEndian.PutUint64(sh[4:12], hdr.startWM)
885			binary.LittleEndian.PutUint64(sh[12:20], hdr.endWM)
886			binary.LittleEndian.PutUint32(sh[20:24], hdr.index)
887			binary.LittleEndian.PutUint32(sh[24:28], seg)
888			// cumulative is filled after the chunk is encoded; entries cannot be
889			// dropped, so the count equals the chunk length.
890			cumulative += uint64(len(chunk))
891			binary.LittleEndian.PutUint32(sh[28:32], uint32(len(chunk)))
892			binary.LittleEndian.PutUint64(sh[32:40], cumulative)
893			if err := write(sh); err != nil {
894				return fail(err)
895			}
896			hs.Write(sh)
897	
898			writeEntry := func(flag byte, key string, value []byte, seq uint64) error {
899				if len(key) > maxRecord || len(value) > maxRecord {
900					return errors.New("snapshot: incremental entry too large")
901				}
902				if flag == ckptFlagPut {
903					ehdr[0] = ckptFlagPut
904				} else {
905					ehdr[0] = ckptFlagDelete
906				}
907				binary.LittleEndian.PutUint32(ehdr[1:5], uint32(len(key)))
908				binary.LittleEndian.PutUint32(ehdr[5:9], uint32(len(value)))
909				binary.LittleEndian.PutUint64(ehdr[9:17], seq)
910				if err := write(ehdr); err != nil {
911					return err
912				}
913				hs.Write(ehdr)
914				if _, err := io.WriteString(w, key); err != nil {
915					return err
916				}
917				hf.Write([]byte(key))
918				hs.Write([]byte(key))
919				if len(value) > 0 {
920					if err := write(value); err != nil {
921						return err
922					}
923					hs.Write(value)
924				}
925				return nil
926			}
927	
928			for _, e := range chunk {
929				if e.delete {
930					if err := writeEntry(ckptFlagDelete, e.key, nil, e.seq); err != nil {
931						return fail(err)
932					}
933				} else {
934					n := anchor.view.lookup(e.key)
935					if n == nil || !n.present || n.seq != e.seq {
936						return fail(errBadBackup)
937					}
938					if err := writeEntry(ckptFlagPut, e.key, cloneBytes(n.value), e.seq); err != nil {
939						return fail(err)
940					}
941				}
942			}
943	
944			var sc [crcSize]byte
945			binary.LittleEndian.PutUint32(sc[:], hs.Sum32())
946			if err := write(sc[:]); err != nil {
947				return fail(err)
948			}
949			segChain = crc32.Update(segChain, crc32.IEEETable, sc[:])
950		}
951	
952		foot := make([]byte, incrFooterSize)
953		binary.LittleEndian.PutUint64(foot[0:8], cumulative)
954		binary.LittleEndian.PutUint32(foot[8:12], segCount)
955		binary.LittleEndian.PutUint32(foot[12:16], segChain)
956		if err := write(foot); err != nil {
957			return fail(err)
958		}
959		var fc [crcSize]byte
960		binary.LittleEndian.PutUint32(fc[:], hf.Sum32())
961		// Flush every buffered byte before appending the terminal CRC: writing it
962		// through the raw file while the bufio writer still held content would
963		// place the CRC at offset 0 and the buffered body after it.
964		if err := w.Flush(); err != nil {
965			return fail(err)
966		}
967		if _, err := tmp.Write(fc[:]); err != nil {
968			return fail(err)
969		}
970		if err := tmp.Sync(); err != nil {
971			return fail(err)
972		}
973		if err := tmp.Close(); err != nil {
974			cleanup()
975			return err
976		}
977	
978		// Promote with link(2): it never overwrites, so a concurrent export cannot
979		// be clobbered, and the ring appears whole or not at all.
980		if err := os.Link(tmpPath, filepath.Join(chainDir, final)); err != nil {
981			if errors.Is(err, os.ErrExist) {
982				cleanup()
983				return errBadBackup
984			}
985			cleanup()
986			return err
987		}
988		if err := syncDirectory(chainDir); err != nil {
989			return err
990		}
991		cleanup()
992		return syncDirectory(chainDir)
993	}
994

