79	// during the merge, rejects the whole operation with an error wrapping
80	// fs.ErrInvalid and leaves the chain exactly as it was. MergeChain on a
81	// closed store returns an error wrapping fs.ErrClosed.
82	func (s *Store) MergeChain(chainDir string, rings int) error {
