124		if err != nil {
125			return err
126		}
127		if uint64(rings) > uint64(art.ringCount) {
128			return errBadBackup
129		}
130		n := rings
131	
132		// Stage the whole merged chain as a sibling of the chain directory so the
133		// final swap is a same-filesystem rename. The chain directory itself is
134		// not touched until the commit.
135		parent := filepath.Dir(chainDir)
136		base := filepath.Base(chainDir)
137		stage, err := os.MkdirTemp(parent, base+mergeStagePrefix)
138		if err != nil {
139			return err
140		}
141		committed := false
142		defer func() {
143			if !committed {
144				os.RemoveAll(stage)
145			}
146		}()
147	
148		// The new head covers the chain through ring n: its export watermark and
149		// cumulative snapshot count are exactly that ring's.
150		tip := art.ringSums[n-1]
151		anchor := backupAnchor{watermark: tip.endWM, snaps: tip.snaps}
152		segs, total, err := mergeChainHead(chainDir, stage, art, n, anchor)
153		if err != nil {
154			return err
155		}
156		if err := writeManifest(stage, stage, anchor, total, segs); err != nil {
157			return err
158		}
159		newHead, err := loadBackupManifest(stage)
160		if err != nil {
161			return err
162		}
163	
164		// Re-encode each surviving ring under its new 1-based index, linked to
165		// the artifact before it in the merged chain. Entries, watermarks and
166		// snapshot counts are carried over unchanged.
167		prevLink := newHead.crc
168		for j := n + 1; j <= int(art.ringCount); j++ {
169			old := art.ringSums[j-1]
170			prev := art.ringSums[j-2]
171			hdr := ringHeader{
172				index:    uint32(j - n),
173				prevLink: prevLink,
174				startWM:  prev.endWM,
175				endWM:    old.endWM,
176				snaps:    old.snaps,
177			}
178			exp := ringExpect{
179				index:    uint32(j),
180				prevLink: prev.fileCRC,
181				startWM:  prev.endWM,
182			}
183			prevLink, err = renumberRing(chainDir, stage, exp, hdr, old.segCount, old.total)
184			if err != nil {
185				return err
186			}
187		}
188	
189		// The staged chain must pass the same whole-chain validation Restore
190		// performs, and it must reach the same tip the original chain reached.
191		newArt, err := validateBackupChain(stage)
192		if err != nil {
193			return err
194		}
195		if newArt.ringCount != art.ringCount-uint32(n) ||
196			newArt.endWM != art.endWM || newArt.snaps != art.snaps {
197			return errBadBackup
198		}
199	
200		// Refuse to commit over a chain that moved since it was validated (an
201		// export or merge driven by another store): the merge is rejected
202		// wholesale and the chain keeps its newer shape.
203		again, err := validateBackupChain(chainDir)
204		if err != nil {
205			return err
206		}
207		if again.head.crc != art.head.crc || again.ringCount != art.ringCount ||
208			again.tipCRC != art.tipCRC || again.endWM != art.endWM ||
209			again.snaps != art.snaps {
210			return errBadBackup
211		}
212	
213		// Commit: move the old chain aside, move the staged chain onto the chain
214		// path, then delete the old chain. A kill before the first rename leaves
215		// the old chain; a kill between the renames leaves the whole old chain in
216		// the trash sibling (swept back into place next time); a kill after the
217		// second rename leaves the complete new chain.
218		trash, err := os.MkdirTemp(parent, base+mergeTrashPrefix)
219		if err != nil {
220			return err
221		}
222		if err := os.Remove(trash); err != nil {
223			return err
224		}
225		if err := os.Rename(chainDir, trash); err != nil {
226			return err
227		}
228		if err := os.Rename(stage, chainDir); err != nil {
229			// Best-effort rollback: the old chain is whole at trash.
230			if rb := os.Rename(trash, chainDir); rb == nil {
231				_ = syncDirectory(parent)
232			}
233			return err
234		}
235		committed = true
236		if err := syncDirectory(parent); err != nil {
237			return err
238		}
239		if err := os.RemoveAll(trash); err != nil {
240			return err
241		}
242		return syncDirectory(parent)
243	}
244	
245	// streamItem carries one entry (or a terminal error) from a chain artifact
246	// being streamed by a goroutine.
247	type streamItem struct {
248		flag  byte
249		key   string
250		value []byte
251		seq   uint64
252		err   error
253	}
254	
255	// mergeStream is the pull side of one streamed chain artifact. The goroutine
256	// validates as it streams, so a consumed stream is a validated artifact.
257	type mergeStream struct {
258		ch   chan streamItem
259		stop chan struct{}
260		cur  streamItem
261		has  bool
262		err  error
263	}
264	
265	// send hands one item to the consumer; it reports errMergeAbort when the
266	// merge has been abandoned, which unwinds the streaming goroutine.
267	func (ms *mergeStream) send(it streamItem) error {
268		select {
269		case ms.ch <- it:
270			return nil
271		case <-ms.stop:
272			return errMergeAbort
273		}
274	}
275	
276	// next advances to the next entry; afterwards has reports whether cur holds
277	// an entry and err holds the stream's terminal error, if any.
278	func (ms *mergeStream) next() {
279		it, ok := <-ms.ch
280		if !ok {
281			ms.has = false
282			return
283		}
284		if it.err != nil {
285			ms.err = it.err
286			ms.has = false
287			return
288		}
289		ms.cur = it
290		ms.has = true
291	}
292	
293	// abort stops the streaming goroutine and lets it exit; it is safe to call
294	// after the stream has already finished.
295	func (ms *mergeStream) abort() {
296		select {
297		case <-ms.stop:
298		default:
299			close(ms.stop)
300		}
301	}
302	
303	// startHeadStream streams the head's segments in order, validating as they
304	// are read.
305	func startHeadStream(dir string, head manifestInfo) *mergeStream {
306		ms := &mergeStream{ch: make(chan streamItem, 1), stop: make(chan struct{})}
307		go func() {
308			defer close(ms.ch)
309			err := streamHeadSegments(dir, head, func(flag byte, key string, value []byte, seq uint64) error {
310				return ms.send(streamItem{flag: flag, key: key, value: value, seq: seq})
311			})
312			if err != nil {
313				ms.send(streamItem{err: err})
314			}
315		}()
316		return ms
317	}
318	
319	// startRingStream streams one ring's entries in order, validating the whole
320	// ring and its linkage against exp as it is read.
321	func startRingStream(dir string, exp ringExpect) *mergeStream {
322		ms := &mergeStream{ch: make(chan streamItem, 1), stop: make(chan struct{})}
323		go func() {
324			defer close(ms.ch)
325			f, err := os.Open(filepath.Join(dir, ringName(exp.index)))
326			if err != nil {
327				ms.send(streamItem{err: err})
328				return
329			}
330			defer f.Close()
331			_, err = scanRing(f, exp, func(flag byte, key string, value []byte, seq uint64) error {
332				return ms.send(streamItem{flag: flag, key: key, value: value, seq: seq})
333			})
334			if err != nil {
335				ms.send(streamItem{err: err})
336			}
337		}()
338		return ms
339	}
340	
341	// mergeChainHead builds the merged head's segments in stage by k-way merging
342	// the old head with the first n rings, all strictly key-ordered streams. For
343	// a key present in several streams the latest ring wins (rings in order, then
344	// the head); a winning tombstone drops the key, so deletes covered by the
345	// merged rings read back as misses. Only one chunk of entries is resident at
346	// a time. It returns the manifest segment records and the total entry count.
347	func mergeChainHead(chainDir, stage string, art artifactInfo, n int, anchor backupAnchor) ([]manifestSegment, uint64, error) {
348		streams := make([]*mergeStream, 0, n+1)
349		streams = append(streams, startHeadStream(chainDir, art.head))
350		prevLink := art.head.crc
351		prevWM := art.head.watermark
352		for j := 1; j <= n; j++ {
353			streams = append(streams, startRingStream(chainDir, ringExpect{
354				index:    uint32(j),
355				prevLink: prevLink,
356				startWM:  prevWM,
357			}))
358			sum := art.ringSums[j-1]
359			prevLink, prevWM = sum.fileCRC, sum.endWM
360		}
361		defer func() {
362			for _, s := range streams {
363				s.abort()
364			}
365		}()
366		for _, s := range streams {
367			s.next()
368		}
369	
370		var segs []manifestSegment
371		var total uint64
372		var segIdx uint32
373		chunk := make([]backupEntry, 0, backupEntriesPerSegment)
374		flush := func() error {
375			if len(chunk) == 0 {
376				return nil
377			}
378			cumulative := total + uint64(len(chunk))
379			crc, err := writeSegment(stage, segIdx, anchor, cumulative, chunk)
380			if err != nil {
381				return err
382			}
383			segs = append(segs, manifestSegment{
384				index:      segIdx,
385				count:      uint32(len(chunk)),
386				cumulative: cumulative,
387				crc:        crc,
388			})
389			total = cumulative
390			segIdx++
391			chunk = chunk[:0]
392			return nil
393		}
394	
395		for {
396			// The smallest key still pending across all streams is next; among
397			// the streams holding it, the latest ring (highest stream index)
398			// holds its terminal state.
399			winner := -1
400			var min string
401			for i, s := range streams {
402				if s.has && (winner < 0 || s.cur.key < min) {
403					min, winner = s.cur.key, i
404				}
405			}
406			if winner < 0 {
407				break
408			}
409			for i, s := range streams {
410				if s.has && s.cur.key == min {
411					winner = i
412				}
413			}
414			if w := streams[winner]; w.cur.flag == ckptFlagPut {
415				chunk = append(chunk, backupEntry{
416					key:     w.cur.key,
417					value:   w.cur.value,
418					seq:     w.cur.seq,
419					present: true,
420				})
421				if len(chunk) == backupEntriesPerSegment {
422					if err := flush(); err != nil {
423						return nil, 0, err
424					}
425				}
426			}
427			for _, s := range streams {
428				if s.has && s.cur.key == min {
429					s.next()
430				}
431			}
432			for _, s := range streams {
433				if s.err != nil {
434					return nil, 0, s.err
435				}
436			}
437		}
438		for _, s := range streams {
439			if s.err != nil {
440				return nil, 0, s.err
441			}
442		}
443		if err := flush(); err != nil {
444			return nil, 0, err
445		}
446		return segs, total, nil
447	}
448	
449	// renumberRing streams the old ring identified by exp out of chainDir,
450	// validates it, and re-encodes it in stage under hdr's new index and link.
451	// The entries, watermarks, snapshot count, segmenting and entry count are
452	// carried over unchanged from the validated ring summary. It returns the new
453	// ring's terminal file CRC, the link the next ring must name.
454	func renumberRing(chainDir, stage string, exp ringExpect, hdr ringHeader, segCount uint32, total uint64) (uint32, error) {
455		src := startRingStream(chainDir, exp)
456		defer src.abort()
457		src.next()
458		crc, err := writeMergedRing(filepath.Join(stage, ringName(hdr.index)), hdr, segCount, total, src)
459		if err != nil {
460			return 0, err
461		}
462		if src.err != nil {
463			return 0, src.err
464		}
465		if src.has {
466			return 0, errBadBackup // more entries than the validated ring declared
467		}
468		return crc, nil
469	}
470	
471	// writeMergedRing streams one ring file at path, pulling exactly total
472	// entries (chunked into segCount segments) from src. The layout is the ring
473	// format writeIncrementalRing emits; only the entry source differs. The file
474	// is fully synced before its CRC is returned.
475	func writeMergedRing(path string, hdr ringHeader, segCount uint32, total uint64, src *mergeStream) (uint32, error) {
476		tmp, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
477		if err != nil {
478			return 0, err
479		}
480		fail := func(err error) (uint32, error) {
481			tmp.Close()
482			os.Remove(path)
483			return 0, err
484		}
485	
486		w := bufio.NewWriter(tmp)
487		hf := crc32.NewIEEE()
488		write := func(b []byte) error {
489			if _, err := w.Write(b); err != nil {
490				return err
491			}
492			hf.Write(b)
493			return nil
494		}
495	
496		head := make([]byte, incrRingHeaderSize)
497		binary.LittleEndian.PutUint32(head[0:4], backupMagic)
498		binary.LittleEndian.PutUint32(head[4:8], backupVersion)
499		binary.LittleEndian.PutUint32(head[8:12], hdr.index)
500		binary.LittleEndian.PutUint32(head[12:16], hdr.prevLink)
501		binary.LittleEndian.PutUint64(head[16:24], hdr.startWM)
502		binary.LittleEndian.PutUint64(head[24:32], hdr.endWM)
503		binary.LittleEndian.PutUint64(head[32:40], hdr.snaps)
504		binary.LittleEndian.PutUint32(head[40:44], segCount)
505		if err := write(head); err != nil {
506			return fail(err)
507		}
508	
509		ehdr := make([]byte, checkpointEntrySize)
510		var segChain uint32
511		var cumulative uint64
512		remaining := total
513		for seg := uint32(0); seg < segCount; seg++ {
514			size := uint64(backupEntriesPerSegment)
515			if remaining < size {
516				size = remaining
517			}
518			remaining -= size
519	
520			hs := crc32.NewIEEE()
521			sh := make([]byte, incrSegHeaderSize)
522			binary.LittleEndian.PutUint32(sh[0:4], backupMagic)
523			binary.LittleEndian.PutUint64(sh[4:12], hdr.startWM)
524			binary.LittleEndian.PutUint64(sh[12:20], hdr.endWM)
525			binary.LittleEndian.PutUint32(sh[20:24], hdr.index)
526			binary.LittleEndian.PutUint32(sh[24:28], seg)
527			cumulative += size
528			binary.LittleEndian.PutUint32(sh[28:32], uint32(size))
529			binary.LittleEndian.PutUint64(sh[32:40], cumulative)
530			if err := write(sh); err != nil {
531				return fail(err)
532			}
533			hs.Write(sh)
534	
535			for i := uint64(0); i < size; i++ {
536				if !src.has {
537					return fail(errBadBackup) // fewer entries than the ring declared
538				}
539				it := src.cur
540				if len(it.key) > maxRecord || len(it.value) > maxRecord {
541					return fail(errBadBackup)
542				}
543				ehdr[0] = it.flag
544				binary.LittleEndian.PutUint32(ehdr[1:5], uint32(len(it.key)))
545				binary.LittleEndian.PutUint32(ehdr[5:9], uint32(len(it.value)))
546				binary.LittleEndian.PutUint64(ehdr[9:17], it.seq)
547				if err := write(ehdr); err != nil {
548					return fail(err)
549				}
550				hs.Write(ehdr)
551				if _, err := io.WriteString(w, it.key); err != nil {
552					return fail(err)
553				}
554				hf.Write([]byte(it.key))
555				hs.Write([]byte(it.key))
556				if len(it.value) > 0 {
557					if err := write(it.value); err != nil {
558						return fail(err)
559					}
560					hs.Write(it.value)
561				}
562				src.next()
563				if src.err != nil {
564					return fail(src.err)
565				}
566			}
567	
568			var sc [crcSize]byte
569			binary.LittleEndian.PutUint32(sc[:], hs.Sum32())
570			if err := write(sc[:]); err != nil {
571				return fail(err)
572			}
573			segChain = crc32.Update(segChain, crc32.IEEETable, sc[:])
574		}
575		if cumulative != total {
576			return fail(errBadBackup)
577		}
578	
579		foot := make([]byte, incrFooterSize)
580		binary.LittleEndian.PutUint64(foot[0:8], cumulative)
581		binary.LittleEndian.PutUint32(foot[8:12], segCount)
582		binary.LittleEndian.PutUint32(foot[12:16], segChain)
583		if err := write(foot); err != nil {
584			return fail(err)
585		}
586		var fc [crcSize]byte
587		binary.LittleEndian.PutUint32(fc[:], hf.Sum32())
588		// Flush every buffered byte before appending the terminal CRC, exactly as
589		// writeIncrementalRing does.
590		if err := w.Flush(); err != nil {
591			return fail(err)
592		}
593		if _, err := tmp.Write(fc[:]); err != nil {
594			return fail(err)
595		}
596		if err := tmp.Sync(); err != nil {
597			return fail(err)
598		}
599		if err := tmp.Close(); err != nil {
600			os.Remove(path)
601			return 0, err
602		}
603		return binary.LittleEndian.Uint32(fc[:]), nil
604	}
605	
606	// sweepMergeDebris clears the sibling directories a merge can leave next to
607	// chainDir when it is killed: a staging chain ("<base>.merge-new-*") and a
608	// retired old chain ("<base>.merge-old-*"). If the chain path itself is
609	// missing but a retired old chain exists, the merge was killed between the
610	// two commit renames and the whole old chain is moved back into place first.
611	// It is best-effort: leftover debris never affects the chain at chainDir.
612	func sweepMergeDebris(chainDir string) {
613		parent := filepath.Dir(chainDir)
614		base := filepath.Base(chainDir)
615		entries, err := os.ReadDir(parent)
616		if err != nil {
617			return
618		}
619		var staging, trash []string
620		for _, e := range entries {
621			if !e.IsDir() {
622				continue
623			}
624			name := e.Name()
625			if isMergeTempName(name, base, mergeStagePrefix) {
626				staging = append(staging, name)
627			}
628			if isMergeTempName(name, base, mergeTrashPrefix) {
629				trash = append(trash, name)
630			}
631		}
632		if len(staging) == 0 && len(trash) == 0 {
633			return
634		}
635		changed := false
636		if _, err := os.Stat(chainDir); errors.Is(err, os.ErrNotExist) && len(trash) > 0 {
637			// Killed between the two commit renames: the old chain is whole in
638			// the trash sibling; put it back before clearing anything.
639			if err := os.Rename(filepath.Join(parent, trash[0]), chainDir); err == nil {
640				changed = true
641				trash = trash[1:]
642			}
643		}
644		for _, name := range staging {
645			if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
646				changed = true
647			}
648		}
649		for _, name := range trash {
650			if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
651				changed = true
652			}
653		}
654		if changed {
655			_ = syncDirectory(parent)
656		}
657	}
658	
659	// isMergeTempName reports whether name is a merge staging or trash directory
660	// for the chain named base.
661	func isMergeTempName(name, base, prefix string) bool {
662		p := base + prefix
663		return len(name) > len(p) && name[:len(p)] == p
664	}
