14	// Restore loads a backup artifact produced by Store.Backup from backupDir and
15	// installs a ready-to-open store into targetDir, returning it already open.
16	// The restored directory, once reopened, is byte-for-byte the complete
17	// committed state at the export watermark: a full replay from it yields the
18	// same terminal state the backup captured, and the cumulative snapshot count
19	// is preserved exactly.
20	//
21	// The artifact is validated as one whole before anything is installed: a
22	// missing segment, a truncated segment, a checksum mismatch, an unknown format
23	// version or a manifest that disagrees with the files rejects the entire
24	// backup with an error wrapping fs.ErrInvalid, and no target is created.
25	//
26	// Installation is all-or-nothing: the new store is fully built and synced in a
27	// temporary sibling directory and only then renamed onto targetDir. A process
28	// killed at any instant leaves either the previous target or one complete
29	// store; a half-built temporary directory is swept by the next Restore or the
30	// next Open of the related directory.
31	//
32	// A backup path that does not exist or is not a directory is rejected with an
33	// error wrapping fs.ErrInvalid. A target path that already exists and is not
34	// empty (including a regular file) is rejected the same way.
35	func Restore(backupDir, targetDir string) (*Store, error) {
36		if backupDir == "" || targetDir == "" {
37			return nil, errBadBackup
38		}
39	
40		// The artifact itself must be an existing directory whose only entries are
41		// the manifest and the segments it names. A merge killed mid-commit next
42		// to the chain is repaired or swept first.
43		sweepMergeDebris(backupDir)
44		binfo, err := os.Stat(backupDir)
45		if err != nil {
46			return nil, errBadBackup
47		}
48		if !binfo.IsDir() {
49			return nil, errBadBackup
50		}
51	
52		// When incremental rings extend the head artifact, the whole chain is
53		// validated up front (missing rings, broken links, discontinuous
54		// watermarks, truncation, checksum failures and unknown versions reject
55		// the entire directory); a head-only artifact keeps its original path.
56		hasRings, err := dirHasRings(backupDir)
57		if err != nil {
58			return nil, err
59		}
60		var chain artifactInfo
61		var manifest manifestInfo
62		if hasRings {
63			chain, err = validateBackupChain(backupDir)
64			if err != nil {
65				return nil, err
66			}
67			manifest = chain.head
68		} else {
69			manifest, err = loadBackupManifest(backupDir)
70			if err != nil {
71				// Content defects already wrap fs.ErrInvalid; an underlying read
72				// failure passes through unchanged.
73				return nil, err
74			}
75			if err := verifyBackupFileSet(backupDir, manifest.segments); err != nil {
76				return nil, err
77			}
78		}
79	
80		// The target must be absent or an empty directory.
81		if err := checkRestoreTarget(targetDir); err != nil {
82			return nil, err
83		}
84	
85		// Build the complete store in a temporary sibling so a kill never exposes
86		// a half-installed target. The sibling lives next to the target so the
87		// final rename is atomic on one filesystem.
88		parent := filepath.Dir(targetDir)
89		if err := os.MkdirAll(parent, 0o700); err != nil {
90			return nil, err
91		}
92		stage, err := os.MkdirTemp(parent, filepath.Base(targetDir)+".restore-*")
93		if err != nil {
94			return nil, err
95		}
96		installed := false
97		defer func() {
98			if !installed {
99				_ = os.RemoveAll(stage)
100			}
101		}()
102	
103		if hasRings {
104			err = buildChainRestoredStore(stage, backupDir, chain)
105		} else {
106			err = buildRestoredStore(stage, backupDir, manifest)
107		}
108		if err != nil {
109			// Artifact validation failures already wrap fs.ErrInvalid; a genuine
110			// write failure is reported as-is rather than mislabeled invalid.
111			return nil, err
112		}
113	
114		if err := installRestoreTarget(stage, targetDir); err != nil {
115			return nil, err
116		}
117		installed = true
118	
119		return Open(targetDir)
120	}
