122	// checkRestoreTarget accepts an absent path or an existing empty directory;
123	// anything else (a regular file, symlink, or non-empty directory) is invalid.
124	func checkRestoreTarget(target string) error {
125		info, err := os.Stat(target)
126		if err != nil {
127			if errors.Is(err, os.ErrNotExist) {
128				return nil
129			}
130			return err
131		}
132		if !info.IsDir() {
133			return errBadBackup
134		}
135		entries, err := os.ReadDir(target)
136		if err != nil {
137			return err
138		}
139		if len(entries) != 0 {
140			return errBadBackup
141		}
142		return nil
143	}
144	
145	// verifyBackupFileSet rejects any entry besides the manifest and exactly the
146	// dense segment set the manifest names, and rejects gaps or extras.
147	func verifyBackupFileSet(backupDir string, segs []manifestSegment) error {
148		entries, err := os.ReadDir(backupDir)
149		if err != nil {
150			return err
151		}
152		want := make(map[uint32]bool, len(segs))
153		for _, s := range segs {
154			if s.index != uint32(len(want)) {
155				return errBadBackup // dense, ordered 0..n-1
156			}
157			want[s.index] = true
158		}
159		got := make(map[uint32]bool, len(segs))
160		for _, e := range entries {
161			if e.IsDir() {
162				return errBadBackup // no staging or foreign directory in a valid artifact
163			}
164			name := e.Name()
165			if name == backupManifest || name == backupManifestTmp {
166				if name == backupManifestTmp {
167					return errBadBackup // an unfinished manifest means an unfinished export
168				}
169				continue
170			}
171			idx, ok := parseSegmentIndex(name)
172			if !ok {
173				return errBadBackup // foreign file
174			}
175			if !want[idx] {
176				return errBadBackup // extra segment
177			}
178			if got[idx] {
179				return errBadBackup
180			}
181			got[idx] = true
182		}
183		if len(got) != len(want) {
184			return errBadBackup // a named segment is missing
185		}
186		return nil
187	}
188	
189	// readFull reads exactly len(buf) bytes from r; a short read (a truncated
190	// artifact) is reported as errBadBackup rather than io.ErrUnexpectedEOF,
191	// while any other read failure passes through.
192	func readFull(r io.Reader, buf []byte) error {
193		if _, err := io.ReadFull(r, buf); err != nil {
194			if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
195				return errBadBackup
196			}
197			return err
198		}
199		return nil
200	}
201	
202	// loadBackupManifest reads and fully validates manifest.dat.
203	func loadBackupManifest(backupDir string) (manifestInfo, error) {
204		var zero manifestInfo
205		f, err := os.Open(filepath.Join(backupDir, backupManifest))
206		if err != nil {
207			// A missing manifest means the export never reached its commit point:
208			// the artifact is incomplete, not a transient I/O failure.
209			if errors.Is(err, os.ErrNotExist) {
210				return zero, errBadBackup
211			}
212			return zero, err
213		}
214		defer f.Close()
215	
216		r := bufio.NewReader(f)
217		head := make([]byte, backupManifestSize)
218		if err := readFull(r, head); err != nil {
219			return zero, err
220		}
221		h := crc32.NewIEEE()
222		h.Write(head)
223	
224		magic := binary.LittleEndian.Uint32(head[0:4])
225		version := binary.LittleEndian.Uint32(head[4:8])
226		if magic != backupMagic || version != backupVersion {
227			return zero, errBadBackup
228		}
229		info := manifestInfo{
230			watermark: binary.LittleEndian.Uint64(head[8:16]),
231			snaps:     binary.LittleEndian.Uint64(head[16:24]),
232			total:     binary.LittleEndian.Uint64(head[24:32]),
233		}
234		n := binary.LittleEndian.Uint32(head[32:36])
235		// Every segment carries at least one entry, so the segment count never
236		// exceeds the entry total; an empty artifact has n == 0 and total == 0.
237		// The absolute cap only guards the pre-allocation against a forged count;
238		// the record loop rejects an artifact that does not actually contain them.
239		if uint64(n) > info.total || n > backupMaxSegments {
240			return zero, errBadBackup
241		}
242	
243		rec := make([]byte, backupSegRecSize)
244		var cumulative uint64
245		info.segments = make([]manifestSegment, 0, n)
246		for i := uint32(0); i < n; i++ {
247			if err := readFull(r, rec); err != nil {
248				return zero, err
249			}
250			h.Write(rec)
251			s := manifestSegment{
252				index:      binary.LittleEndian.Uint32(rec[0:4]),
253				count:      binary.LittleEndian.Uint32(rec[4:8]),
254				cumulative: binary.LittleEndian.Uint64(rec[8:16]),
255				crc:        binary.LittleEndian.Uint32(rec[16:20]),
256			}
257			if s.index != i {
258				return zero, errBadBackup
259			}
260			cumulative += uint64(s.count)
261			if s.cumulative != cumulative || s.count == 0 {
262				return zero, errBadBackup
263			}
264			info.segments = append(info.segments, s)
265		}
266		if cumulative != info.total {
267			return zero, errBadBackup
268		}
269	
270		var crcb [crcSize]byte
271		if err := readFull(r, crcb[:]); err != nil {
272			return zero, err
273		}
274		if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() {
275			return zero, errBadBackup
276		}
277		info.crc = binary.LittleEndian.Uint32(crcb[:])
278		if _, err := r.ReadByte(); !errors.Is(err, io.EOF) {
279			return zero, errBadBackup // trailing bytes, or an underlying read error
280		}
281		return info, nil
282	}
283	
284	// buildRestoredStore streams every named segment into a fresh wal.log in the
285	// staging directory, validating each segment as it reads. The result is a WAL
286	// whose full replay reproduces the exported terminal state (one terminal
287	// frame per key, the same shape a compaction writes), followed by the snapshot
288	// count meta. Nothing is installed until this whole step succeeds.
289	func buildRestoredStore(stage, backupDir string, info manifestInfo) error {
290		wf, err := os.OpenFile(filepath.Join(stage, walName), os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
291		if err != nil {
292			return err
293		}
294		fail := func(err error) error {
295			wf.Close()
296			return err
297		}
298		l := &walWriter{f: wf, w: bufio.NewWriter(wf)}
299	
300		var seen uint64
301		var lastKey string
302		haveKeys := false
303	
304		for _, seg := range info.segments {
305			f, err := os.Open(filepath.Join(backupDir, segmentName(seg.index)))
306			if err != nil {
307				return fail(err)
308			}
309			r := bufio.NewReader(f)
310			hdr := make([]byte, backupSegHeaderSize)
311			if err := readFull(r, hdr); err != nil {
312				f.Close()
313				return fail(err)
314			}
315			h := crc32.NewIEEE()
316			h.Write(hdr)
317	
318			magic := binary.LittleEndian.Uint32(hdr[0:4])
319			version := binary.LittleEndian.Uint32(hdr[4:8])
320			watermark := binary.LittleEndian.Uint64(hdr[8:16])
321			snaps := binary.LittleEndian.Uint64(hdr[16:24])
322			index := binary.LittleEndian.Uint32(hdr[24:28])
323			count := binary.LittleEndian.Uint32(hdr[28:32])
324			cumulative := binary.LittleEndian.Uint64(hdr[32:40])
325			if magic != backupMagic || version != backupVersion ||
326				watermark != info.watermark || snaps != info.snaps ||
327				index != seg.index || count != seg.count || cumulative != seg.cumulative {
328				f.Close()
329				return fail(errBadBackup)
330			}
331	
332			ehdr := make([]byte, checkpointEntrySize)
333			for i := uint32(0); i < count; i++ {
334				if err := readFull(r, ehdr); err != nil {
335					f.Close()
336					return fail(err)
337				}
338				h.Write(ehdr)
339				flag := ehdr[0]
340				keyLen := binary.LittleEndian.Uint32(ehdr[1:5])
341				valLen := binary.LittleEndian.Uint32(ehdr[5:9])
342				seq := binary.LittleEndian.Uint64(ehdr[9:17])
343				if (flag != ckptFlagPut && flag != ckptFlagDelete) ||
344					keyLen == 0 || keyLen > maxRecord || valLen > maxRecord ||
345					(flag == ckptFlagDelete && valLen != 0) {
346					f.Close()
347					return fail(errBadBackup)
348				}
349				body := make([]byte, int(keyLen)+int(valLen))
350				if err := readFull(r, body); err != nil {
351					f.Close()
352					return fail(err)
353				}
354				h.Write(body)
355				key := string(body[:keyLen])
356				// Entries must be strictly ascending and unique across segments.
357				if haveKeys && key <= lastKey {
358					f.Close()
359					return fail(errBadBackup)
360				}
361				lastKey, haveKeys = key, true
362				value := body[keyLen:]
363				if flag == ckptFlagPut {
364					if err := l.encodeFrameSeq(opPutSeq, key, seq, value); err != nil {
365						f.Close()
366						return fail(err)
367					}
368				} else {
369					if err := l.encodeFrameSeq(opDeleteSeq, key, seq, nil); err != nil {
370						f.Close()
371						return fail(err)
372					}
373				}
374			}
375	
376			var crcb [crcSize]byte
377			if err := readFull(r, crcb[:]); err != nil {
378				f.Close()
379				return fail(err)
380			}
381			if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() ||
382				binary.LittleEndian.Uint32(crcb[:]) != seg.crc {
383				f.Close()
384				return fail(errBadBackup)
385			}
386			if _, err := r.ReadByte(); !errors.Is(err, io.EOF) {
387				f.Close()
388				return fail(errBadBackup)
389			}
390			f.Close()
391			seen += uint64(count)
392		}
393	
394		if seen != info.total {
395			return fail(errBadBackup)
396		}
397		if info.snaps > 0 {
398			var v [metaValueSize]byte
399			binary.LittleEndian.PutUint64(v[:], info.snaps)
400			if err := l.encodeFrame(opMeta, "", v[:]); err != nil {
401				return fail(err)
402			}
403		}
404		if err := l.w.Flush(); err != nil {
405			return fail(err)
406		}
407		if err := wf.Sync(); err != nil {
408			return fail(err)
409		}
410		if err := wf.Close(); err != nil {
411			return err
412		}
413		return syncDirectory(stage)
414	}
415	
416	// installRestoreTarget puts the fully built staging store onto target. The
417	// target is absent or empty: when it exists as an empty directory it is
418	// removed first, so the rename lands on no existing entry. A crash in between
419	// leaves either an empty/absent target or the complete store, never a partial
420	// one.
421	func installRestoreTarget(stage, target string) error {
422		if info, err := os.Stat(target); err == nil && info.IsDir() {
423			if err := os.Remove(target); err != nil {
424				return err
425			}
426			if err := syncDirectory(filepath.Dir(target)); err != nil {
427				return err
428			}
429		}
430		if err := os.Rename(stage, target); err != nil {
431			return err
432		}
433		return syncDirectory(filepath.Dir(target))
434	}
435	
436	// sweepRestoreDebris removes a half-built temporary restore directory left
437	// next to dir by a kill during Restore. It only ever removes the specific
438	// sibling names Restore creates.
439	func sweepRestoreDebris(dir string) {
440		parent := filepath.Dir(dir)
441		base := filepath.Base(dir)
442		entries, err := os.ReadDir(parent)
443		if err != nil {
444			return
445		}
446		fixed := base + ".restore.tmp"
447		for _, e := range entries {
448			name := e.Name()
449			if !e.IsDir() {
450				continue
451			}
452			if name == fixed || isRestoreTempName(name, base) {
453				_ = os.RemoveAll(filepath.Join(parent, name))
454			}
455		}
456		_ = syncDirectory(parent)
457	}
458	
459	// isRestoreTempName matches MkdirTemp's "<base>.restore-<random>" directories.
460	func isRestoreTempName(name, base string) bool {
461		prefix := base + ".restore-"
462		return len(name) > len(prefix) && name[:len(prefix)] == prefix
463	}
464	
465	// openBackupSweep cleans incomplete-backup debris found when opening a
466	// directory that was used as a backup output: a staging directory or manifest
467	// temp is always debris, and finished segments are debris only when the
468	// manifest that completes the artifact is absent. A complete artifact is left
469	// untouched.
470	func openBackupSweep(dir string) error {
471		if err := sweepBackupDebris(dir); err != nil {
472			return err
473		}
474		if _, err := os.Stat(filepath.Join(dir, backupManifest)); err == nil {
475			return nil // complete artifact; leave it in place
476		}
477		entries, err := os.ReadDir(dir)
478		if err != nil {
479			return err
480		}
481		var names []string
482		for _, e := range entries {
483			if e.IsDir() {
484				continue
485			}
486			if isBackupSegmentName(e.Name()) {
487				names = append(names, e.Name())
488			}
489			if _, ok := parseRingIndex(e.Name()); ok {
490				names = append(names, e.Name())
491			}
492		}
493		sort.Strings(names)
494		for _, name := range names {
495			if err := os.Remove(filepath.Join(dir, name)); err != nil &&
496				!errors.Is(err, os.ErrNotExist) {
497				return err
498			}
499		}
500		if len(names) > 0 {
501			return syncDirectory(dir)
502		}
503		return nil
504	}
505

