1	// Package snapshot implements a persistent key-value store whose readers
2	// operate on immutable point-in-time snapshots. A snapshot never observes a
3	// write committed after it was acquired, and it keeps serving its fixed view
4	// even after the store that produced it has been closed.
5	package snapshot
6	
7	import (
8		"errors"
9		"io/fs"
10		"os"
11		"sync"
12		"sync/atomic"
13	)
14	
15	// viewFlattenLimit bounds how deep an overlay chain a published view grows
16	// before the next commit builds it on a flattened copy. Without a bound the
17	// chain would gain one map per commit for the life of the store and memory
18	// would track cumulative commits; flattening every viewFlattenLimit commits
19	// keeps live depth (and the work a read or checkpoint walk does) independent
20	// of commit count, while the flattened copies stay immutable for every
21	// snapshot already holding an older view.
22	const viewFlattenLimit = 64
23	
24	// node is one immutable version in a key's history. Versions form a linked
25	// list from newest to oldest; a snapshot pins the head current when it was
26	// acquired, so overwritten and deleted values stay readable through every
27	// view that references them. seq is the version's commit number, unique and
28	// strictly increasing along each key's chain; it orders versions across the
29	// independent chains that meet again during a pinning compaction.
30	type node struct {
31		value   []byte
32		present bool   // false marks a delete; a present nil/empty value is still a hit
33		seq     uint64 // commit order, 1-based
34		older   *node
35	}
36	
37	// view is an immutable map of keys to their newest version. Rather than
38	// copying the whole map for every commit, a view is a thin overlay: its own
39	// keys on top of a base view it never modifies. Reads descend the short chain
40	// of overlays; the current view, snapshots and cursors simply point at one.
41	//
42	// A view's keys map may itself hold the whole keyspace: the base layer
43	// (base == nil) used by recovery, compaction and periodic flattening. Maps
44	// are never mutated after publication, so reading them needs no lock; only
45	// the commit path, which has just created a fresh overlay, writes its keys.
46	type view struct {
47		keys  map[string]*node
48		base  *view
49		depth int // number of overlays from this view to its flat base
50	}
51	
52	// newView returns an empty overlay atop base (nil for a flat base view).
53	func newView(base *view) *view {
54		d := 1
55		if base != nil {
56			d = base.depth + 1
57		}
58		return &view{keys: make(map[string]*node), base: base, depth: d}
59	}
60	
61	// lookup returns the newest version recorded for key anywhere along the
62	// overlay chain, or nil when the key was never written.
63	func (v *view) lookup(key string) *node {
64		for cur := v; cur != nil; cur = cur.base {
65			if n, ok := cur.keys[key]; ok {
66				return n
67			}
68		}
69		return nil
70	}
71	
72	// rangeEach visits the terminal version of every distinct key, fn once per
73	// key, walking newest-to-oldest so an overlay entry shadows its base.
74	func (v *view) rangeEach(fn func(key string, n *node) bool) {
75		seen := make(map[string]struct{})
76		for cur := v; cur != nil; cur = cur.base {
77			for k, n := range cur.keys {
78				if _, ok := seen[k]; ok {
79					continue
80				}
81				seen[k] = struct{}{}
82				if !fn(k, n) {
83					return
84				}
85			}
86		}
87	}
88	
89	// flatten materializes one flat map holding the view's complete terminal
90	// state. It allocates a fresh map and shares only immutable nodes, so views
91	// already published stay untouched.
92	func (v *view) flatten() *view {
93		flat := newView(nil)
94		v.rangeEach(func(k string, n *node) bool {
95			flat.keys[k] = n
96			return true
97		})
98		return flat
99	}
100	
101	// Store is an open key-value store backed by a directory on disk.
102	type Store struct {
103		mu sync.Mutex // serializes writers and guards the fields below
104	
105		dir       string
106		wal       *walWriter
107		current   atomic.Pointer[view] // latest committed view; lock-free for readers
108		snapshots atomic.Uint64        // cumulative number of snapshots handed out
109		nextSeq   uint64               // highest commit sequence handed out; guarded by mu
110	
111		// chain is the in-memory record of the usable checkpoint layers paired
112		// with the current WAL, oldest first. Empty means no checkpoint is live
113		// (the next Checkpoint writes a base). Compaction re-anchors it against
114		// the replacement log; Checkpoint appends a delta and prunes the window.
115		chain []layerState
116		// dirty keys were touched by effective commits strictly after the newest
117		// layer in chain; they are exactly the keys the next delta layer covers.
118		// nil until the first such commit.
119		dirty []string
120		// legacyLive reports that a version-1 single-file snapshot.ckpt was the
121		// checkpoint paired with the WAL at open and has not been replaced by a
122		// layered chain or retired by compaction. Compaction must durably retire
123		// it before swapping the WAL, exactly as it retires a layered chain.
124		legacyLive bool
125	
126		// Open cursors pin their fixed view's versions against compaction. The
127		// set is read by Compact (which holds mu) and mutated at cursor
128		// open/close, using cursorMu; reads never take either lock.
129		cursorMu sync.Mutex
130		cursors  map[*Cursor]struct{}
131	
132		// Group-commit queue. Every state-changing commit (single Put/Delete just
133		// like CommitBatch) that arrives while another commit is forcing the log
134		// lines up here; one leader drains the queue, encodes the waiting commits
135		// and shares a single flush plus fsync across them.
136		// queueMu only ever guards this queue and committer; it is never held
137		// across disk I/O, so readers and enqueuers never wait on a sync.
138		queueMu   sync.Mutex
139		queue     []*pendingBatch
140		committer bool
141	
142		// backupMu serializes exports that stage into one chain directory
143		// (BackupIncremental) so two exports on this store never share their
144		// staging directory. It is independent of mu: it is held across the
145		// export's disk I/O and never blocks commits or lock-free reads.
146		backupMu sync.Mutex
147	
148		// Test hook, nil outside tests. leaderHook runs once after a commit has
149		// become leader, before its first queue drain, and lets tests hold a
150		// leader until a known number of commits have coalesced.
151		leaderHook func()
152	
153		closed atomic.Bool
154	}
155	
156	// Snapshot is a stable read-only view of a store captured at one instant. It
157	// owns no store resources of its own and stays usable after the store has
158	// been closed; a cursor opened from it does register with the store while it
159	// pins versions.
160	type Snapshot struct {
161		v     atomic.Pointer[view] // nil once the snapshot is closed
162		store *Store               // back-reference for cursor pin accounting
163	}
164	
165	// Open opens or creates a persistent store in dir. A path that names a
166	// regular file rather than a directory returns an error wrapping
167	// fs.ErrInvalid.
168	func Open(dir string) (*Store, error) {
169		info, err := os.Stat(dir)
170		if err == nil {
171			if !info.IsDir() {
172				return nil, errNotDir
173			}
174		} else {
175			if !errors.Is(err, fs.ErrNotExist) {
176				return nil, err
177			}
178			if err := os.MkdirAll(dir, 0o700); err != nil {
179				return nil, err
180			}
181		}
182	
183		// A replacement log from a compaction killed before its rename can never
184		// be complete state of record; the old wal.log is. Drop the stale file.
185		// Likewise, staging debris from a kill mid-checkpoint (a half-built layer
186		// temp or a legacy single-file temp) is swept: only finished layers are
187		// ever read.
188		if err := removeStaleCompact(dir); err != nil {
189			return nil, err
190		}
191		if err := sweepCheckpointDebris(dir); err != nil {
192			return nil, err
193		}
194		if err := sweepStagedChain(dir); err != nil {
195			return nil, err
196		}
197		// Sweep debris from a hot backup that was killed before its manifest, and
198		// from a restore killed before its target rename. These names never appear
199		// in a live store, so a store that was merely backed up is unaffected.
200		if err := openBackupSweep(dir); err != nil {
201			return nil, err
202		}
203		sweepRestoreDebris(dir)
204		// Sweep sibling debris a chain merge killed mid-commit can leave next to
205		// a directory that was used as a backup chain.
206		sweepMergeDebris(dir)
207	
208		latest := newView(nil)
209		var replaySeq uint64
210		var snapshotCount uint64
211		var validSize int64
212		var chain []layerState
213		var tailTouched []string
214		var legacyLive bool
215	
216		// apply installs one replayed record into the latest view. Legacy
217		// records (written before sequence numbers existed) carry no seq; replay
218		// order is commit order, so number them sequentially.
219		apply := func(op byte, key string, value []byte, seq uint64) {
220			if seq == 0 {
221				replaySeq++
222				seq = replaySeq
223			} else if seq > replaySeq {
224				replaySeq = seq
225			}
226			switch op {
227			case opPut, opPutSeq:
228				latest.keys[key] = &node{value: cloneBytes(value), present: true, seq: seq, older: latest.keys[key]}
229			case opDelete, opDeleteSeq:
230				latest.keys[key] = &node{present: false, seq: seq, older: latest.keys[key]}
231			}
232		}
233	
234		// Fast reopen: seed memory from the longest valid checkpoint-chain prefix
235		// and replay only the WAL written after its last layer. A layer is
236		// accepted only as a whole and only when it links to the layer before; a
237		// missing, truncated, checksum-bad, unknown-version or unlinked layer
238		// rejects it and every layer after it, and recovery falls back to the
239		// previous layer, to the legacy single-file checkpoint, or finally to a
240		// from-scratch WAL replay.
241		chainInfo, chainErr := readChain(dir)
242		if chainErr != nil {
243			return nil, chainErr
244		}
245		// Reject the suffix outright: anything beyond the longest intact, linked
246		// prefix is removed as a whole so a broken layer never pairs with the WAL
247		// and never occupies space. Half a layer is never installed.
248		pruneRejectedChainFiles(dir, len(chainInfo.layers))
249		walLen, sizeErr := walFileSize(dir)
250		if sizeErr != nil {
251			return nil, sizeErr
252		}
253		// The selected layer's cut must lie inside this exact WAL. Cuts are
254		// nondecreasing along the chain, so any suffix whose cut ran past the end
255		// of the file is rejected as a whole down to the last pairable layer.
256		for len(chainInfo.layers) > 0 && chainInfo.layers[len(chainInfo.layers)-1].offset > walLen {
257			removeRejectedChainSuffix(dir, chainInfo.layers[len(chainInfo.layers)-1].index)
258			chainInfo.layers = chainInfo.layers[:len(chainInfo.layers)-1]
259		}
260	
261		switch {
262		case len(chainInfo.layers) > 0:
263			// Compose the valid prefix: each layer overrides the one it builds on.
264			var last layerState
265			for _, l := range chainInfo.layers {
266				for _, e := range l.entries {
267					latest.keys[e.key] = &node{value: cloneBytes(e.value), present: e.present, seq: e.seq}
268				}
269				last = l
270			}
271			chain = chainInfo.layers
272			replaySeq = last.seq
273			// Replay the tail, remembering touched keys so the first delta layer
274			// taken in this opening also covers commits already past the cut.
275			tailApply := func(op byte, key string, value []byte, seq uint64) {
276				if op == opPut || op == opPutSeq || op == opDelete || op == opDeleteSeq {
277					tailTouched = append(tailTouched, key)
278				}
279				apply(op, key, value, seq)
280			}
281			var rerr error
282			validSize, snapshotCount, rerr = replayWALTail(dir, last.offset, last.snaps, tailApply)
283			if rerr != nil {
284				return nil, rerr
285			}
286		default:
287			// No layered chain: accept a legacy version-1 checkpoint if one is
288			// intact and pairs with this WAL, otherwise replay the whole log.
289			cp, cpOK, cpErr := loadLegacyCheckpoint(dir)
290			if cpErr != nil {
291				removeRejectedLegacy(dir)
292				cpOK = false
293			}
294			if cpOK && (cp.offset < 0 || cp.offset > walLen) {
295				removeRejectedLegacy(dir)
296				cpOK = false
297			}
298			if cpOK {
299				legacyLive = true
300				for _, e := range cp.entries {
301					latest.keys[e.key] = &node{value: cloneBytes(e.value), present: e.present, seq: e.seq}
302				}
303				replaySeq = cp.seq
304				validSize, snapshotCount, err = replayWALTail(dir, cp.offset, cp.snaps, apply)
305				if err != nil {
306					return nil, err
307				}
308			} else {
309				validSize, snapshotCount, err = replayWAL(dir, apply)
310				if err != nil {
311					return nil, err
312				}
313			}
314		}
315	
316		wal, err := openWALWriter(dir, validSize)
317		if err != nil {
318			return nil, err
319		}
320	
321		s := &Store{
322			dir:        dir,
323			wal:        wal,
324			cursors:    make(map[*Cursor]struct{}),
325			nextSeq:    replaySeq,
326			chain:      chain,
327			dirty:      dedupeKeys(nil, tailTouched),
328			legacyLive: legacyLive,
329		}
330		s.snapshots.Store(snapshotCount)
331		s.current.Store(latest)
332		return s, nil
333	}
334	
335	// dedupeKeys returns app's distinct keys appended to dst, first occurrence
336	// wins, preserving order.
337	func dedupeKeys(dst, src []string) []string {
338		seen := make(map[string]struct{}, len(src))
339		out := dst
340		for _, k := range src {
341			if _, ok := seen[k]; ok {
342				continue
343			}
344			seen[k] = struct{}{}
345			out = append(out, k)
346		}
347		return out
348	}
349	
350	// Put stores value under key. An empty key returns an error wrapping
351	// fs.ErrInvalid. A nil or empty value is stored as-is: a following Get on the
352	// key reports a hit. The store does not keep a reference to value.
353	//
354	// Put is exactly a one-op batch: it joins the same group-commit queue as
355	// CommitBatch, so a single write and concurrent batches can share one disk
356	// sync while each keeps its own crash atomicity.
357	func (s *Store) Put(key string, value []byte) error {
358		if s.closed.Load() {
359			return errStoreClosed
360		}
361		if key == "" {
362			return errEmptyKey
363		}
364		return s.commit([]BatchOp{{Key: key, Value: value}})
365	}
366	
367	// Delete removes key. Deleting an empty key returns an error wrapping
368	// fs.ErrInvalid; deleting a key that was never written or is already deleted
369	// is not an error and commits nothing. It joins the same group-commit queue a
370	// batch uses.
371	func (s *Store) Delete(key string) error {
372		if s.closed.Load() {
373			return errStoreClosed
374		}
375		if key == "" {
376			return errEmptyKey
377		}
378		return s.commit([]BatchOp{{Key: key, Delete: true}})
379	}
380	
381	type pendingBatch struct {
382		ops  []BatchOp
383		done chan error // buffered(1); the leader delivers the commit result
384	}
385	
386	// commitPlan is one queued batch resolved against the cumulative state built
387	// up across its whole sync group.
388	type commitPlan struct {
389		view  *view // cumulative view after this batch; nil when it committed nothing
390		dirty []string
391	}
392	
393	// BatchOp is one change in a batch committed with CommitBatch. Delete false
394	// stores Value under Key (a nil or empty Value is still a hit); Delete true
395	// removes Key.
396	type BatchOp struct {
397		Key    string
398		Value  []byte
399		Delete bool
400	}
401	
402	// commit enqueues ops as one atomic framed commit and drives the leader loop.
403	// Single-key Put/Delete and CommitBatch are all this one path.
404	func (s *Store) commit(ops []BatchOp) error {
405		if s.closed.Load() {
406			return errStoreClosed
407		}
408		if err := validateBatchOps(ops); err != nil {
409			return err
410		}
411	
412		me := &pendingBatch{ops: ops, done: make(chan error, 1)}
413	
414		// Enqueue. queueMu guards only the queue and the leader flag and is
415		// never held across disk I/O, so followers can join a group while the
416		// leader is syncing and readers never wait.
417		s.queueMu.Lock()
418		if s.closed.Load() {
419			s.queueMu.Unlock()
420			return errStoreClosed
421		}
422		s.queue = append(s.queue, me)
423		if s.committer {
424			s.queueMu.Unlock()
425			return <-me.done // the running leader will drain this batch
426		}
427		s.committer = true
428		s.queueMu.Unlock()
429	
430		// Test-only rendezvous: invoked once by the elected leader before its
431		// first queue drain. Production leaves it nil.
432		if s.leaderHook != nil {
433			s.leaderHook()
434		}
435	
436		// Leadership: drain groups until the queue is empty. Each group takes
437		// s.mu while it forces the log, which serializes it with Snapshot,
438		// Checkpoint, Compact and Close, so a group never straddles a log swap or
439		// a layer capture.
440		for {
441			s.queueMu.Lock()
442			// Resign and re-check the queue under one critical section, so a
443			// batch enqueuing in this instant either observes the still-active
444			// leader or becomes the next one; no batch can be left queued with
445			// no leader to drain it.
446			if len(s.queue) == 0 {
447				s.committer = false
448				s.queueMu.Unlock()
449				break
450			}
451			group := s.queue
452			s.queue = nil
453			s.queueMu.Unlock()
454			for p, rerr := range s.commitGroup(group) {
455				group[p].done <- rerr
456			}
457		}
458	
459		return <-me.done
460	}
