462	// CommitBatch applies a group of writes and deletes as one atomic commit:
463	// the whole batch becomes visible together or not at all, and snapshots and
464	// cursors fixed at any instant see either the state before the batch or the
465	// state after it, never an in-between mixture. Changes are applied in list
466	// order; a later change to the same key overrides an earlier one within the
467	// batch. Concurrent batches take effect in commit (enqueue) order, and a
468	// later committed batch's same-key change overrides an earlier one's.
469	//
470	// Batches committed concurrently (with single Put/Delete calls among them)
471	// share the disk sync: one leader drains the queue, encodes every waiting
472	// commit as its own recoverable framed commit and forces them all with one
473	// flush plus fsync, so N commits arriving together cost one sync while each
474	// stays whole on recovery; a commit that arrives while a sync is in flight
475	// rides the next one. Reads take none of these locks and are never blocked by
476	// the sync.
477	//
478	// If any change has an empty key the whole batch is rejected before it is
479	// queued or committed: an error wrapping fs.ErrInvalid is returned, no frame
480	// is written and the store's state is unchanged. A delete of a key that is
481	// absent or already deleted commits nothing, exactly like Delete; a batch
482	// containing only such no-ops (or an empty slice) commits nothing and
483	// returns nil. CommitBatch on a closed store returns an error wrapping
484	// fs.ErrClosed.
485	//
486	// Each batch is forced to stable storage before its call returns and is
487	// published as one new view; a process killed mid-commit therefore reopens
488	// with the entire batch present or entirely absent. The store does not keep
489	// references to the op Value slices after return.
490	func (s *Store) CommitBatch(ops []BatchOp) error {
491		return s.commit(ops)
492	}
493	
494	// validateBatchOps checks argument-only invariants before a batch is queued.
495	// Empty keys map to fs.ErrInvalid, exactly as for Put and Delete.
496	func validateBatchOps(ops []BatchOp) error {
497		for i := range ops {
498			if ops[i].Key == "" {
499				return errEmptyKey
500			}
501		}
502		for i := range ops {
503			if len(ops[i].Key) > maxRecord || (!ops[i].Delete && seqSize+len(ops[i].Value) > maxRecord) {
504				return errRecordTooLarge()
505			}
506		}
507		return nil
508	}
509	
510	func errRecordTooLarge() error { return errors.New("snapshot: record too large") }
511	
512	// commitGroup encodes and forces every queued batch with one flush and one
513	// sync, then publishes one view per effective batch in queue (commit) order.
514	// It returns one result per batch. An encoding or sync failure fails the
515	// whole group: nothing it contained is published or sequenced. The single
516	// committer calls this; s.mu is taken for the entire force, exactly as the
517	// view transitions and checkpoint watermarks need.
518	func (s *Store) commitGroup(group []*pendingBatch) []error {
519		results := make([]error, len(group))
520	
521		s.mu.Lock()
522		defer s.mu.Unlock()
523		if s.closed.Load() || s.wal == nil {
524			// Close ran between the drain and the lock; nothing can commit.
525			for i := range results {
526				results[i] = errStoreClosed
527			}
528			return results
529		}
530	
531		// Remember where the group starts so any failure can rewind the log:
532		// unacknowledged frames must not linger at EOF and reappear under a
533		// later commit or after a reopen. Nothing is buffered here (the previous
534		// group always flushed), so EOF is the exact offset.
535		groupStart, posErr := s.wal.position()
536		if posErr != nil {
537			for i := range results {
538				results[i] = posErr
539			}
540			return results
541		}
542		rollback := func(cause error) []error {
543			if err := s.wal.truncateTo(groupStart); err != nil {
544				cause = errors.Join(cause, err)
545			}
546			for i := range results {
547				results[i] = cause
548			}
549			return results
550		}
551	
552		base := s.current.Load()
553		seq := s.nextSeq
554		plans := make([]commitPlan, 0, len(group))
555		encodedAny := false
556		var groupDirty []string
557	
558		// head caches the group-cumulative terminal node of every key the queued
559		// batches touch: a nil entry means "known absent in base". It is sized by
560		// the batches' distinct keys, never by the live keyspace. The baseline
561		// flattened the whole view inside this loop every viewFlattenLimit queued
562		// batches, so a long queue behind one sync copied the live keyspace once
563		// per viewFlattenLimit batches; now each touched key walks the (already
564		// bounded) overlay chain at most once and at most one full keyspace map is
565		// built per group, after the last overlay.
566		head := make(map[string]*node)
567		resolve := func(key string) *node {
568			if n, ok := head[key]; ok {
569				return n // nil records a key known to be absent
570			}
571			n := base.lookup(key)
572			head[key] = n
573			return n
574		}
575	
576		for _, p := range group {
577			// Each batch gets its own thin immutable overlay on the previous
578			// batch's overlay, so the view it publishes is a valid point-in-time
579			// state independent of later batches, and queued batches cost memory
580			// proportional to their own ops rather than the whole live keyspace.
581			v := newView(base)
582			var changes []batchChange
583			for i := range p.ops {
584				op := &p.ops[i]
585				headNode := resolve(op.Key)
586				if op.Delete {
587					if headNode == nil || !headNode.present {
588						continue // idempotent no-op, matching the single Delete
589					}
590					seq++
591					nn := &node{present: false, seq: seq, older: headNode}
592					changes = append(changes, batchChange{key: op.Key, seq: seq, delete: true})
593					v.keys[op.Key] = nn
594					head[op.Key] = nn
595				} else {
596					seq++
597					value := cloneBytes(op.Value)
598					nn := &node{value: value, present: true, seq: seq, older: headNode}
599					changes = append(changes, batchChange{key: op.Key, seq: seq, value: value})
600					v.keys[op.Key] = nn
601					head[op.Key] = nn
602				}
603			}
604			if len(changes) > 0 {
605				if err := s.wal.encodeBatch(changes); err != nil {
606					return rollback(err)
607				}
608				encodedAny = true
609				for i := range changes {
610					groupDirty = append(groupDirty, changes[i].key)
611				}
612			}
613			var planView *view
614			if len(changes) > 0 {
615				planView = v
616			}
617			plans = append(plans, commitPlan{view: planView})
618			base = v
619		}
620	
621		if encodedAny {
622			// One flush, one fsync for the whole group. Return means every
623			// encoded batch in it is durable as a self-contained framed commit.
624			if err := s.wal.flushSync(); err != nil {
625				return rollback(err)
626			}
627		}
628	
629		s.nextSeq = seq
630		// Publish one view per effective batch in queue order, so each batch's
631		// state becomes observable atomically as its own point-in-time view. Then,
632		// whenever the chain reached the depth bound, publish one flattened final
633		// view. That flatten builds one full keyspace map at most (after the last
634		// overlay) and keeps read depth and the next group's baseline bounded by
635		// viewFlattenLimit rather than by queue length; the baseline built one full
636		// map per viewFlattenLimit queued batches inside the loop.
637		var finalFlat *view
638		if base.depth >= viewFlattenLimit {
639			finalFlat = base.flatten()
640		}
641		for _, plan := range plans {
642			if plan.view != nil {
643				s.current.Store(plan.view)
644			}
645		}
646		if finalFlat != nil {
647			s.current.Store(finalFlat)
648		}
649		s.dirty = dedupeKeys(s.dirty, groupDirty)
650		return results
651	}
