653	// Get returns the latest committed value for key. Empty keys, keys never
654	// written and deleted keys are all misses: ok is false and err is nil. The
655	// returned bytes are owned by the caller.
656	func (s *Store) Get(key string) ([]byte, bool, error) {
657		if s.closed.Load() {
658			return nil, false, errStoreClosed
659		}
660		if key == "" {
661			return nil, false, nil
662		}
663		val, ok := lookupView(s.current.Load(), key)
664		return val, ok, nil
665	}
