667	// Compact reclaims history: values that were overwritten or deleted and are
668	// not needed by any open snapshot or cursor are dropped from memory and the
669	// write-ahead log is atomically rewritten, so the directory occupies less
670	// space than before whenever reclaimable history existed.
671	//
672	// When a checkpoint chain is live, compaction keeps the generations inside
673	// the retention window and re-anchors them against the replacement log: that
674	// log is written as one segment per surviving layer (its prefix reproducing
675	// the layer's terminal state at a fresh cut), followed by the post-window
676	// changes and the snapshot-count meta, and the rebuilt layers reference those
677	// cuts. Generations outside the window are retired together with the old
678	// chain and stop occupying space immediately.
679	//
680	// Every open snapshot keeps its exact fixed view; every open cursor keeps
681	// paging through its exact fixed sequence, and the one version per key its
682	// view shows stays in the rewritten log until the cursor closes; the next
683	// compaction then reclaims it and shrinks the directory further. A process
684	// killed at any point during compaction reopens in a complete commit state,
685	// with every successful write, deletion and the cumulative snapshot count
686	// intact; no intermediate file needs a second compaction or checkpoint to
687	// repair.
688	//
689	// Compact serializes with writes, deletes, snapshots, cursor opens, closing
690	// and other compactions (the group-commit leader and every other mutator
691	// take the same lock); concurrent or repeated calls queue and all return nil.
692	// Compacting a closed store returns an error wrapping fs.ErrClosed.
693	func (s *Store) Compact() error {
694		s.mu.Lock()
695		defer s.mu.Unlock()
696		if s.closed.Load() {
697			return errStoreClosed
698		}
699	
700		cur := s.current.Load()
701	
702		// Pinned versions, keyed by commit sequence (globally unique). The
703		// current head of every live key in the latest view is retained; each
704		// open cursor additionally pins the single head version its fixed view
705		// shows for every present key in its range. A deleted key's tombstone is
706		// retained only when a cursor still reads an older value under it, so
707		// replay links that value as the tombstone's predecessor; otherwise the
708		// key is dropped from the rewritten log altogether, as before.
709		pinned := make(map[uint64]*node)
710		keySeqs := make(map[string][]uint64)
711		cursorPins := make(map[string]bool)
712		pin := func(k string, n *node) {
713			if n == nil {
714				return
715			}
716			if _, ok := pinned[n.seq]; !ok {
717				pinned[n.seq] = n
718				keySeqs[k] = append(keySeqs[k], n.seq)
719			}
720		}
721		for _, c := range s.openCursors() {
722			for _, k := range c.keys {
723				cursorPins[k] = true
724				pin(k, c.v.lookup(k)) // exactly the version this cursor pages out
725			}
726		}
727		for k, n := range keySetOf(cur) {
728			if n.present || cursorPins[k] {
729				pin(k, n) // live head, or a tombstone shielding a pinned value
730			}
731		}
732	
733		plan := buildCompactionPlan(pinned, keySeqs)
734		snapshotCount := s.snapshots.Load()
735	
736		// The surviving window, oldest first. Layers before it are retired.
737		window := checkpointWindow
738		if window > len(s.chain) {
739			window = len(s.chain)
740		}
741		first := len(s.chain) - window
742		windowLayers := s.chain[first:]
743		hadChain := len(s.chain) > 0
744		// paired reports any checkpoint — layered chain or a legacy single file —
745		// whose cut belongs to the WAL about to be replaced. It must be withdrawn
746		// before the swap so no checkpoint is ever read against a different log.
747		paired := hadChain || s.legacyLive
748	
749		// Phase 1 (nothing live is touched yet): build and sync the complete
750		// replacement log, and when layers survive, the matching staged chain.
751		// Any failure here removes the staged files and leaves the store and the
752		// old WAL/chain exactly as they were, so committing can continue.
753		var seg *segmentedWAL
754		if !hadChain {
755			if err := buildCompactWAL(s.dir, plan.histories(), snapshotCount); err != nil {
756				return err
757			}
758		} else {
759			// Full terminal state at each window layer's watermark, composed from
760			// the complete old chain (including the generations about to retire).
761			termStates := make([][]checkpointEntry, window)
762			for w := 0; w < window; w++ {
763				termStates[w] = composeLayers(s.chain[:first+w+1])
764			}
765			seg = planSegmentedWAL(plan, windowLayers, termStates, cur)
766			if err := buildSegmentedCompactArtifacts(s.dir, seg, snapshotCount); err != nil {
767				return err
768			}
769		}
770	
771		// Phase 2: the replacement must never meet a paired checkpoint on reopen.
772		// Durably withdraw the whole layered chain and/or the legacy file while
773		// the old wal.log is still in place; a crash after this but before the
774		// rename simply replays the old log in full. Failure precedes any
775		// stateful move, so drop the staged files and leave the store untouched.
776		if paired {
777			if err := retireChain(s.dir); err != nil {
778				removeStaleCompact(s.dir)
779				removeStagedChain(s.dir)
780				return err
781			}
782			s.legacyLive = false
783		}
784		oldWAL := s.wal
785		if err := oldWAL.close(); err != nil {
786			// Staged files have not become state of record; remove them and
787			// reopen a writer on the untouched old log, so no repair-only
788			// intermediate lingers and the next commit proceeds.
789			removeStaleCompact(s.dir)
790			removeStagedChain(s.dir)
791			reopened, openErr := openWALWriter(s.dir, -1)
792			if openErr != nil {
793				return err
794			}
795			s.wal = reopened
796			return err
797		}
798		// Phase 3: atomically rename the temp over wal.log, force the directory
799		// and open a writer on the new log. If the rename never landed the old
800		// log is intact and committing continues (staged chain is dropped).
801		nextWAL, renamed, installErr := installCompactWAL(s.dir)
802		if nextWAL == nil {
803			// The rename landed but the new log cannot be opened: the directory
804			// is not in a state where further commits are safe, so mark the
805			// store closed rather than leaving a handle only another compaction
806			// could repair.
807			s.closed.Store(true)
808			s.wal = nil
809			return installErr
810		}
811		s.wal = nextWAL
812		if renamed {
813			s.current.Store(plan.freshView())
814			if hadChain {
815				// dropCheckpoint clears any in-memory and on-disk chain so the
816				// next Checkpoint starts a fresh base with no O_EXCL collision.
817				dropCheckpoint := func() {
818					s.chain = nil
819					s.dirty = nil
820					os.RemoveAll(checkpointDirPath(s.dir))
821				}
822				if window == 0 {
823					dropCheckpoint()
824					removeStagedChain(s.dir)
825				} else if err := activateStagedChain(s.dir); err != nil {
826					// The new WAL is already live; rather than leave a half
827					// installed chain, run with no live checkpoint. The next
828					// Checkpoint establishes a fresh base.
829					dropCheckpoint()
830				} else {
831					info, ierr := readChain(s.dir)
832					if ierr != nil || len(info.layers) != window {
833						dropCheckpoint()
834					} else {
835						s.chain = info.layers
836						s.dirty = seg.tailKeys
837					}
838				}
839			}
840		} else if hadChain {
841			// Rename failed; the old WAL stayed. retireChain already removed the
842			// old chain, so drop the staged replacement as well: no checkpoint
843			// pairs with this WAL. Committing continues; the next Checkpoint heals.
844			removeStagedChain(s.dir)
845			s.chain = nil
846			s.dirty = nil
847		}
848		return installErr
849	}
