851	// keySetOf returns the distinct keys present anywhere in the view.
852	func keySetOf(v *view) map[string]*node {
853		out := make(map[string]*node)
854		v.rangeEach(func(k string, n *node) bool {
855			out[k] = n
856			return true
857		})
858		return out
859	}
