861	// Checkpoint appends one self-describing, checksummed layer to the checkpoint
862	// chain so the next Open seeds memory from the longest intact layer prefix
863	// and replays only the write-ahead log written after it, instead of replaying
864	// the whole log. The first layer (the base) holds complete committed state;
865	// every later layer covers only commits after the layer it builds on.
866	// Checkpoint changes nothing visible: every committed write and deletion, the
867	// cumulative snapshot count and every open snapshot or cursor are unaffected,
868	// and reads keep hitting memory without touching disk.
869	//
870	// Producing a layer and making it live are two distinct steps: the layer is
871	// captured under the write lock, built fully under a temporary name and
872	// forced to stable storage, then atomically renamed into place and linked to
873	// the previous layer by a content hash. A kill at any instant leaves either
874	// the old complete chain or the chain extended by one complete layer; reopen
875	// observes one complete committed state, never a half layer (staging debris
876	// is swept on the next open).
877	//
878	// Only checkpointWindow newest generations are kept: appending past the
879	// window rebuilds the chain with the oldest surviving layer as a fresh full
880	// base against the unchanged WAL and deletes the retired layers immediately.
881	//
882	// Checkpoint serializes with writes, batch commits, snapshots, cursor opens,
883	// compaction and closing (it takes the same write lock), but never with
884	// lock-free reads: Get, scans, snapshot reads and cursor paging proceed while
885	// it runs. A batch stays wholly on one side of the captured cut, and history
886	// pinned by open snapshots or cursors is left untouched. On a closed store
887	// Checkpoint returns an error wrapping fs.ErrClosed.
888	func (s *Store) Checkpoint() error {
889		s.mu.Lock()
890		defer s.mu.Unlock()
891		if s.closed.Load() {
892			return errStoreClosed
893		}
894	
895		offset, err := s.wal.position()
896		if err != nil {
897			return err
898		}
899		cur := s.current.Load()
900		snaps := s.snapshots.Load()
901	
902		if len(s.chain) == 0 {
903			// First layer: full base state. This also upgrades a legacy
904			// single-file directory: the old file is removed once the base is
905			// staged, and the WAL it pairs with has not changed.
906			layer := capturedLayer{
907				index:   0,
908				entries: captureView(cur),
909				offset:  uint64(offset),
910				seq:     s.nextSeq,
911				snaps:   snaps,
912			}
913			if err := installLayer(s.dir, layer); err != nil {
914				return err
915			}
916			if err := removeLegacyCheckpoint(s.dir); err != nil {
917				return err
918			}
919			s.legacyLive = false
920		} else {
921			last := s.chain[len(s.chain)-1]
922			layer := capturedLayer{
923				index:   last.index + 1,
924				prevCRC: last.crc,
925				entries: captureDelta(cur, s.dirty),
926				offset:  uint64(offset),
927				seq:     s.nextSeq,
928				snaps:   snaps,
929			}
930			if err := installLayer(s.dir, layer); err != nil {
931				return err
932			}
933		}
934	
935		info, err := readChain(s.dir)
936		if err != nil {
937			return err
938		}
939		s.chain = info.layers
940		s.dirty = nil
941	
942		// Enforce the retention window: keep only the newest checkpointWindow
943		// layers, rebuilt as a standalone chain against the same unchanged WAL.
944		if len(s.chain) > checkpointWindow {
945			if err := s.rebaseChainToWindow(); err != nil {
946				return err
947			}
948		}
949		return nil
950	}
951	
952	// rebaseChainToWindow rebuilds the live chain so only the newest
953	// checkpointWindow layers remain: the oldest kept layer becomes a fresh full
954	// base (materialized from the complete in-memory chain) at its existing WAL
955	// cut, and the layers after it keep their delta content at their existing
956	// cuts. The WAL is not touched.
957	func (s *Store) rebaseChainToWindow() error {
958		keep := checkpointWindow
959		if keep > len(s.chain) {
960			keep = len(s.chain)
961		}
962		first := len(s.chain) - keep
963		// Materialize full terminal state at the oldest kept layer.
964		full := composeLayers(s.chain[:first+1])
965		newLayers := make([]capturedLayer, 0, keep)
966		newLayers = append(newLayers, capturedLayer{
967			index: 0, entries: full,
968			offset: uint64(s.chain[first].offset),
969			seq:    s.chain[first].seq,
970			snaps:  s.chain[first].snaps,
971		})
972		for j := first + 1; j < len(s.chain); j++ {
973			newLayers = append(newLayers, capturedLayer{
974				index:   uint32(j - first),
975				entries: s.chain[j].entries,
976				offset:  uint64(s.chain[j].offset),
977				seq:     s.chain[j].seq,
978				snaps:   s.chain[j].snaps,
979			})
980		}
981		if err := replaceCheckpointChain(s.dir, newLayers); err != nil {
982			return err
983		}
984		info, err := readChain(s.dir)
985		if err != nil {
986			return err
987		}
988		s.chain = info.layers
989		return nil
990	}
991	
992	// composeLayers returns the full terminal state after applying layers in
993	// order (each overriding the one before), sorted by key for a canonical base.
994	func composeLayers(layers []layerState) []checkpointEntry {
995		term := make(map[string]checkpointEntry)
996		for _, l := range layers {
997			for _, e := range l.entries {
998				term[e.key] = e // later layer wins; tombstones survive as tombstones
999			}
1000		}
1001		out := make([]checkpointEntry, 0, len(term))
1002		for _, e := range term {
1003			out = append(out, e)
1004		}
1005		sortEntries(out)
1006		return out
1007	}
