1009	// openCursors snapshots the set of currently open cursors. Cursor views and
1010	// bounds are immutable after opening, so reading their fields here needs no
1011	// per-cursor lock.
1012	func (s *Store) openCursors() []*Cursor {
1013		s.cursorMu.Lock()
1014		defer s.cursorMu.Unlock()
1015		cs := make([]*Cursor, 0, len(s.cursors))
1016		for c := range s.cursors {
1017			cs = append(cs, c)
1018		}
1019		return cs
1020	}
