1022	// Snapshot acquires a stable view. It never observes writes committed after
1023	// it returns, and keeps serving that view regardless of later writes,
1024	// deletes or Store.Close, until the Snapshot itself is closed.
1025	func (s *Store) Snapshot() (*Snapshot, error) {
1026		s.mu.Lock()
1027		defer s.mu.Unlock()
1028		if s.closed.Load() {
1029			return nil, errStoreClosed
1030		}
1031		count := s.snapshots.Add(1)
1032		if err := s.wal.appendMeta(count); err != nil {
1033			s.snapshots.Add(^uint64(0))
1034			return nil, err
1035		}
1036		snap := &Snapshot{store: s}
1037		snap.v.Store(s.current.Load())
1038		return snap, nil
1039	}
1040	
1041	// Get reads key from the snapshot's fixed view. Old values overwritten or
1042	// deleted afterwards are still readable; keys created afterwards, empty
1043	// keys and keys absent or deleted when the snapshot was taken are misses. A
1044	// read from a closed snapshot is also a plain miss, never an error. The
1045	// returned bytes are owned by the caller.
1046	func (s *Snapshot) Get(key string) ([]byte, bool) {
1047		if key == "" {
1048			return nil, false
1049		}
1050		v := s.v.Load()
1051		if v == nil {
1052			return nil, false // closed snapshot
1053		}
1054		n := v.lookup(key)
1055		if n == nil || !n.present {
1056			return nil, false
1057		}
1058		return cloneBytes(n.value), true
1059	}
1060	
1061	// Close releases the snapshot's fixed view. Closing more than once is a
1062	// no-op returning nil.
1063	func (s *Snapshot) Close() error {
1064		s.v.Store(nil)
1065		return nil
1066	}
1067	
1068	// Close flushes and closes the store. Data already committed stays complete
1069	// and readable after reopening the directory. Snapshots still open keep
1070	// serving their fixed views until closed themselves; closing an already
1071	// closed store is a no-op returning nil.
1072	func (s *Store) Close() error {
1073		s.mu.Lock()
1074		if !s.closed.CompareAndSwap(false, true) {
1075			s.mu.Unlock()
1076			return nil
1077		}
1078		wal := s.wal
1079		s.wal = nil
1080		s.mu.Unlock()
1081	
1082		return wal.close()
1083	}
1084	
1085	func lookupView(v *view, key string) ([]byte, bool) {
1086		n := v.lookup(key)
1087		if n == nil || !n.present {
1088			return nil, false
1089		}
1090		return cloneBytes(n.value), true
1091	}
1092	
1093	func cloneBytes(b []byte) []byte {
1094		if b == nil {
1095			return nil
1096		}
1097		c := make([]byte, len(b))
1098		copy(c, b)
1099		return c
1100	}
