func acquireChainLease(chainDir string) (*chainLease, error) {
	parent := filepath.Dir(chainDir)
	if info, err := os.Stat(parent); err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, errBadBackup
		}
		return nil, err
	} else if !info.IsDir() {
		return nil, errBadBackup
	}
	path := filepath.Join(parent, filepath.Base(chainDir)+chainLeaseSuffix)
	for attempt := 0; attempt < 8; attempt++ {
		l, err := tryAcquireLease(path)
		if err == nil {
			return l, nil
		}
		if !errors.Is(err, os.ErrExist) {
			return nil, err
		}
		stale, err := leaseIsStale(path)
		if err != nil {
			return nil, err
		}
		if !stale {
			return nil, errBadBackup
		}
		// Reclaim the dead holder's lease. Another contender may win the
		// removal or the next create; either way the loop re-reads the state.
		_ = os.Remove(path)
	}
	return nil, errBadBackup
}
