func leaseIsStale(path string) (bool, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return true, nil // already gone; the create retry will succeed
		}
		return false, err
	}
	pid, _, expiry, ok := parseLease(data)
	if !ok {
		// Not a readable lease: either a foreign file or one caught mid-write.
		// Reclaim it only once it is clearly old, so a live writer finishing
		// its create is never clobbered.
		info, serr := os.Stat(path)
		if serr != nil {
			if errors.Is(serr, os.ErrNotExist) { return true, nil }
			return false, serr
		}
		return time.Since(info.ModTime()) > leaseTTL, nil
	}
	if alive, certain := processAlive(pid); certain {
		if !alive {
			return true, nil
		}
	}
	return time.Now().UnixNano() > expiry, nil
}
