// Prepare the output directory and clear debris from an export killed
// mid-run, before touching the store. A finished artifact or any foreign
// entry is never overwritten. Debris from a chain merge killed mid-commit
// next to this directory is repaired or swept first.
sweepMergeDebris(outDir)
info, err := os.Stat(outDir)
if err != nil {
	if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	if err := os.MkdirAll(outDir, 0o700); err != nil {
		return err
	}
} else if !info.IsDir() {
	return errBadBackup
}
// Coordinate with every other operation on this chain directory, in this
// process or another: only the lease holder may clear debris and write an
// artifact here. A live holder fails the whole export; a killed holder's
// lease is reclaimed.
lease, err := acquireChainLease(outDir)
if err != nil {
	return err
}
defer lease.release()
if err := prepareBackupDir(outDir); err != nil {
	return err
}

